export default [{"id":3816,"title":"هزيمة العثمانيين أمام المجريين والنمساويين .","date":["العام الهجري :1001","العام الميلادي :1592"],"text":"بعد أن قُتِل الوزير محمد الصقلي وكثُرت التوليةُ والعزلُ بعده, وقد كان هو عمادَ الدولة وركنَها، ومع توقُّف الحروب التي كانت تباشِرُها الإنكشارية الذين أخذوا في الثورة والاعتداء والنَّهبِ والسرقة، فثاروا في إستانبول والقاهرة وغيرها، ثمَّ لما أعيد سنان باشا لولاية الصدر الأعظم، أشار بأن تسيَّرَ العساكر الإنكشارية إلى المجر، وهذا ما تمَّ، ولكِنَّ الجيش الذي كان قد تعوَّد الفوضى اختَلَّ نظامُه, فانهزم أمام النمسا التي قامت بدعم المجر."},{"id":3817,"title":"هجوم الألمان على العثمانيين  .","date":["العام الهجري :1001","الشهر القمري : رمضان","العام الميلادي :1593"],"text":"قام الجيش الألماني البالغ 40 ألف مقاتل بهجومٍ مباغت على الجيشِ العثماني المكوَّن مِن 10 آلاف مقاتلٍ في الجنوب الشرقي من زغرب الواقعة حاليًّا في كرواتيا، وقَتل 7 آلاف عثماني، بمن فيهم القائِدُ حسن باشا حاكِمُ البوسنة. وكانت هذه الغارة سببًا في إعلان تركيا الحربَ على ألمانيا."},{"id":3818,"title":"إعلان الدولة العثمانية الحرب على ألمانيا .","date":["العام الهجري :1001","الشهر القمري : شوال","العام الميلادي :1593"],"text":"أعلنت الدولةُ العثمانية الحربَ على ألمانيا بعد الغارةِ التي شنَّها الجيشُ الألماني على الجيش العثمانيِّ على ضفافِ نهر كولبا قُربَ حدود البوسنة، وكان هذا في عهد مراد الثالث من 982- 1003، وقد راح ضحيَّةَ هذه الغارة 7 آلاف عثماني, وأنهت هذه الحربُ حالةَ الصلح التي استمرت 25 عامًا بين الدولتين."},{"id":3819,"title":"قيام حكومة آفراسياب في البصرة تابعة للعثمانيين\n  .","date":["العام الهجري :1002","العام الميلادي :1593"],"text":"كانت البصرةُ واحدةً مِن المدُنِ التي شَهِدت الكثيرَ مِن الحركاتِ الثورية ضِدَّ الولاة العثمانيين؛ إذ تمكَّن الثوارُ من عزل ولاية البصرةِ عن باقي ولايات العراق، فبرزت أُسرة في جنوب العراق، وهي أُسرة أحد كبار ملَّاكي الأراضي من العرب، ويُدعى آفراسياب، وكان مؤسِّس هذه الأُسرة يشغلُ منصِبَ قائد القوَّات غير النظامية لحاكم البصرة أيوب باشا، فاستغل آفراسياب حالةَ الضعف التي شهدتها البصرةُ، ولم يتمكن الوالي أيوب باشا من مواجهة الاضطرابات والثوراتِ التي شَهِدتْها البصرة، الأمرُ الذي اضطره إلى بيع منصبه لآفراسياب بثمانية أكياس رومية، كلُّ كيس يضم ثلاثة آلاف درهم. ما إن تسلَّم آفراسياب مقاليدَ الأُمور في البصرة حتى أرسل إلى السلطان العثماني في إسطنبول مبعوثًا يؤكِّد فيه ولاءه وتبعيته للدولة العثمانية التي كانت خلال هذه الفترة منشغلةً لحد كبير في القضاءِ على تمرُّد القوات العسكرية التي أضعَفَت الدولة العثمانية من الداخل، وانعكس ذلك الضَّعفُ في أن خَسِرت الكثيرَ مِن سيادتها في العراق، فأصدر الباب العالي فرمانًا يعترف فيه بآفراسياب عاملًا على ولاية البصرة على ألَّا يَقطَع آفراسياب الخطبةَ عن السلطان العثماني، وأن يدفَعَ الجراية السنوية للحكومة العثمانية، فوافق آفراسياب على هذه الشروطِ، فلم يقطَعْ صلاته بالبابِ العالي، وكان يبعثُ بالرسائل إلى إسطنبول يبيِّن فيها ولاءَه للسلطان العثماني، وكانت تلك الرسائلُ تَبعثُ على الارتياح لدى حكومةِ إسطنبول التي كانت تُدرِك جيدًا خصوصية البصرة من الناحية السياسية والاقتصادية، وبهذا تمكَّن آفراسياب من أن يكَوِّن أُسرةً محليةً حاكمةً مُستقلةً عن الدولة العثمانية."},{"id":3820,"title":"غزو العثمانيين ألمانيا .","date":["العام الهجري :1002","الشهر القمري : ذي القعدة","العام الميلادي :1594"],"text":"اجتاز القائِدُ العثماني قوجاسنان باشا الحدودَ الألمانية، وسيطر على مدينة \"يانق قلعة\" التي تقع على بعد 100 كم من الجنوب الشرقي لفيينا، وهي تعدُّ المنفذَ الرئيسيَّ لفيينا، وقد تمت السيطرةُ على هذه المدينة بعد حصار استمرَّ 51 يومًا."},{"id":3821,"title":"وفاة السلطان العثماني مراد الثالث بن سليم الثاني .","date":["العام الهجري :1003","العام الميلادي :1594"],"text":"هو السُّلطانُ العثماني مرادُ الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني. ولِدَ سنة 951. قال عبد الملك العصامي المكي: \"نشأ مرادٌ في ظِلِّ والده وجَدِّه على مهاد العِزِّ والسلطان في حجرِ الخلافةِ، راضعًا ثديَ العلم والعرفان، ولم تُعلَم له صبوةٌ مع توفُّرِ دواعيها، ولم يتناول شيئًا من المحرَّمات، بل ولا مِن المكروهات؛ فهو منذ ترعرع في شبابه صانه اللهُ عن المحاربة والمخاصمة الناشئة عن حظوظِ النفسِ وحبِّ الرئاسة، واستعمل نفسَه في العلم والعمل، ثم في الاستعداد للخلافة الإسلاميةِ، مع كمال النزاهة والعفَّة والنفاسة، ومنها أنَّ طريقته في الملبس والمأكل والمشرب والمركب طريقةُ الصالحين والزهَّاد ما عدا ما فيه خَلَل لنظام المُلك أو ضرر للعباد، وكان جلوسُه على تخت الخلافة الإسلامية في ثامِنِ شهر رمضان في اليوم الذي توفِّي أبوه فيه من عام 982، فجلس جلوسًا جامعًا لفضل الزمان والمكان، ومنحه الله تعالى من كثرة الخَراجِ والخزائن والعساكر ما لم يجمَعْه أحدٌ من أسلافه الأكابر، فإذا عزم على فتحِ أعظمِ الممالك جهَّزَ شرذمةً من عساكره المنصورة، ففتح كلَّ صعبِ المسالك، ومن النعمة العظمى إتمامُ عمارة المسجد الحرامِ الذي بُدئ بترميمِه في زمان جَدِّه السلطان سليمان سنة 980 وتمام التعمير في زمانه\" توفِّيَ مراد الثالث عن عمر يناهز 49 عامًا، ودفن في فناء أيا صوفيا، فكانت مدةُ حكمه عشرين سنة وثمانية أشهر، ثم تولى بعده ابنُه محمد الثالث الذي جلس على سرير السلطنة بعد وفاة والده باثني عشر يومًا؛ لأنَّه كان مقيمًا في مغنيسا."},{"id":3822,"title":"قتل السلطان العثماني محمد الثالث إخوانه التسعة عشر  .","date":["العام الهجري :1003","العام الميلادي :1594"],"text":"ذُكِرَ أنَّ السلطان محمد الثالث بدأ حكمَه بقتل تسعة عشر أخًا من إخوته الذكور، وأمر أن يُدفَنوا مع أبيه حتى لا ينافِسوه في الحُكم، كما أمر بقتلِ عشر نساءٍ من نساء أبيه كلُّهن حبالى، وهذا بعيد لا يقبلُه لا عقلٌ ولا شرعٌ، وترفضه الفِطَر السوية، وهو من الاتهامات التي حَرَص أعداءُ وخصوم الدولة على تشويه سير سلاطينها بمثل هذا الاتهام, وصرْف الأنظار عن بطولاتهم وإنجازاتهم التي حقَّقوها خلال حكمهم للمسلمين أكثرَ من أربعة قرون؛ فالسلطان محمد الثالث هذا كتَبَ الله على يده انتصاراتٍ عظيمةً لم يستطع تحقيقَها كثيرٌ من أسلافِه، على الرغم من قوَّتهم، كسليمان القانوني!"},{"id":3823,"title":"استيلاء الألمان على قلعة إستركون من العثمانيين .","date":["العام الهجري :1003","الشهر القمري : ذي القعدة","العام الميلادي :1595"],"text":"استولى الألمان على قلعة إستركون الواقعة على الطريق بين بودابست وفيينا من العثمانيين. وكان السلطانُ العثماني سليمان القانوني قد فتح هذه القلعةَ قبل 52 عامًا. واستمرَّ الاحتلال الألماني للقلعة 10 سنوات نهبوا خلالها آثارَها التاريخية."},{"id":3824,"title":"قوات المغرب الأقصى تعبر الصحراء الكبرى لتنهي إمبراطورية سنغاي .","date":["العام الهجري :1004","العام الميلادي :1595"],"text":"بلغت إمبراطورية سنغاي أوْجَ قوَّتها في عهد الأسقيين، وأبرزهم محمد الكبير وابنه داود، وقد كانت إمبراطوريتهم انتشرت وتوسَّعت حتى وصلت إلى مالي ومشارفِ المجيد، ولامست الصحراءَ الكبرى، وانتصروا على الموسي ومالي والطوارق وبني حسان، حتى جاء أحمد الذهبي زعيمُ السعديين في المغرب الأقصى وجهز جيشًا ليس بالكبير، وكان مؤلَّفًا من ثلاثة آلاف جندي، مات أكثَرُ من نصفهم في طريقهم إلى السنغاي؛ بسبب سوء الأحوال وما أصابهم في الطريق من مشقَّات، ثم استطاع هذا الأميرُ بمن بقي معه أن يدخلوا عاصمةَ سنغاي غاو، ودمَّروها واحتلُّوا تمبكتو وغوغو أيضًا، فتراجع فيها تألُّقُ المسلمين وبقي سلاطينُ المغرب محتفظين بممتلكاتهم فيها حتى نهاية القرن الثاني عشر الهجري، أمَّا من بقي من الأُسرة الحاكمة الأسقية، فبقوا يحكمون على رأس دولةٍ قليلة الشأن في المناطق الجنوبية التي لم يَطُلْها الاحتلال."},{"id":3825,"title":"انتصار العثمانيين على النمسا والمجر في معركة كرزت .","date":["العام الهجري :1004","العام الميلادي :1595"],"text":"لما هُزِمَ الجيش العثماني الإنكشاري أمام النمسا والمجر عام 1001 أعلن أمراءُ الأفلاق والبغدان وترانسلفانيا التمَرُّدَ على الدولة العثمانية، وانضمُّوا إلى النمسا في حربها ضِدَّ العثمانيين، فسار السلطانُ محمد الثالث ومعه سنان باشا إلى بلغراد، ومنها إلى ميادين الوغى والجهاد، وبمجرَّد خروجه دبَّت في جيش السلطان الحميَّة الدينية والغَيرة العسكريَّة، ففتحوا قلعةَ أرلو الحصينة التي عجز السلطانُ سليمان عن فتحِها سنة 1556م, ودمَّروا جيوشَ المجر والنمسا في معركةِ كرزت بالقرب من قلعة أرلو، حتى شُبِّهت هذه الموقعة بواقعة (موهاكز) التي انتصر فيها السلطان سليمان سنة 1526م، ودخل بخارست عاصِمة الأفلاق، لكنَّ أميرَها قام برَدِّ فعلٍ استطاع فيه أن يحرِزَ نصرًا اضطرَّ العثمانيين أن ينهزموا إلى ما بعد نهر الدانوب."},{"id":3826,"title":"مقتل 4 آلاف تركي في مدينة بوخارست .","date":["العام الهجري :1004","الشهر القمري : ربيع الأول","العام الميلادي :1595"],"text":"قُتِل 4 آلاف تركي في مدينة بوخارست ذبحًا بالسيف، أثناء عصيانِ عددٍ من الإمارات العثمانية في المجر ورومانيا للدولة العثمانيةِ."},{"id":3827,"title":"وفاة شمس الدين الرملي الشافعي .","date":["العام الهجري :1004","الشهر القمري : جمادى الأولى","العام الميلادي :1596"],"text":"هو شمسُ الدين محمد بن أحمد بن حمزة الرملي الشافعي، نسبةً إلى الرملة من قرى المنوفية بمصر، ولِدَ بالقاهرة سنة 919, وهو فقيهُ الديار المصرية في عصره، برع في الفقهِ الشافعيِّ حتى قيل عنه الشافعيُّ الصغير. قال عنه الشوكاني: \"لم أقفْ له على ترجمةٍ مبسوطة، لكن قال العصامي في وصفه: إمامُ الحرمين وشيخُ المصريين، من كانت العلماء تكتبُ عنه ما يُملي؛ مولانا شمس الدين محمد بن أحمد بن حمزة الرملي، فاتح أقفال مشكلات العلوم، ومحيي ما اندرس منها من الآثار والرسوم، أستاذ الأستاذين, وأحد علماء الدين، علامة المحققين على الإطلاق، وفهامة المدقِّقين بالاتفاق\" له مصنَّفات أشهرها: نهاية المحتاج إلى شرح المنهاج في الفقه الشافعي، وله غاية المرام في شرح شروط المأموم والإمام، وله عمدة الرابح في الفقه أيضًا، وغيرها من المصنَّفات، توفي في القاهرة."},{"id":3828,"title":"ثورة الناصر ابن السلطان الغالب بالله ببلاد الريف ومقتله. .","date":["العام الهجري :1004","الشهر القمري : رمضان","العام الميلادي :1596"],"text":"لما توفِّيَ الغالب بالله، قام بالأمر بعده ابنه المتوكِّلُ، فقبض على أخيه الناصر فاعتقله، فلم يزل معتقلًا عنده سائِرَ أيامه، إلى أن قَدِمَ عبد الملك المعتصم بجيشِ الترك وانتزع المُلكَ من يد ابن أخيه المتوكِّل، فسرَّح الناصر من اعتقالِه وأحسن إليه، فلم يزل عنده في أرغَدِ عيش إلى أن توفِّيَ المعتصم يوم وادي المخازن، وأفضى الأمر إلى أحمد المنصور، ففرَّ الناصر إلى آصيلا، وكانت للنصارى يومئذٍ، ثم عبر البحرَ منها إلى الأندلس، فكان عند طاغية قشتالة مدةً طويلةً إلى أن سرَّحه الطاغية إلى المغرب؛ بقصد تفريق كلمة المسلمين وإحداثِ الشِّقاقِ بينهم، فخرج الناصر بمليلية ونزل بها لثلاث مضت من شعبان سنة 1003 وتسامعت به الغوغاء والطَّغامُ من أهل تلك البلاد، فأقبلوا إليه يَزِفُّون، فكثرت جموعُه وتوفَّرت جيوشُه، واهتزَّ المغرِبُ بأسره لذلك، ثم إنَّ الناصر خرج من مليلية قاصدًا تازا فدخلها واستولى عليها، ونزعت إليه القبائلُ المجاورة لها كالبرانس وغيرهم، فتألَّبوا عليه وتمالؤوا على إعزازِه ونصرِه، ولَمَّا دخل تازا طالَبَ أهلَها بالمُكس، وقال لهم: إن النصارى يغرمون حتى على البيضِ، ولما سمع المنصورُ بخبره أقلقه ذلك وتخوَّف منه غاية الخوف؛ لأنَّ الناصر اهتَزَّ المغرب لقيامه وتشوَّفت النفوس إليه؛ لميل القلوب عن المنصور؛ لشدَّة وطأته واعتسافه للرعية، فبعث إليه جيشًا وافرًا، فهزمهم الناصر واستفحل أمرُه وتمكَّن ناموسه من القلوبِ، فأمر المنصور وليَّ عهده المأمون بمنازلته، فخرج إليه من فاس في تعبئة حسنة وهيئة تامة، فلما التقى الجمعان كانت الدائرة على الناصر بالموضع المعروف بالحاجبِ، وفَرَّ على وجهه فاحتَلَّ بالجاية بلدةً من عمل بلاد الزبيب، فلحق به وليُّ العهد فلم يزل في مقاتلته إلى أن قَبَض عليه فقطع رأسَه، وبعث به إلى مراكش، وكان ذلك سنة 1005 وقيل سنة 1004 يوم الثلاثاء الثالث والعشرين من رمضان، وهو الأصح."},{"id":3829,"title":"الاستعمار الهولندي لجزر أندونيسيا .","date":["العام الهجري :1005","العام الميلادي :1596"],"text":"وصل الهولنديون إلى سومطرة وجاوه، وحدث بينهم وبين السكَّان معاركُ، وحاول البرتغاليون الوقوفَ في وجه الهولنديين، فتحرَّكوا بسفُنِهم ضِدَّهم، وكان الأندونيسيون قد تحالفوا ضِمنًا مع الهولنديين ضد البرتغاليين؛ ظنًّا منهم أنهم سيتخلَّصون من الحقد البرتغالي الصليبي، فتزحزح البرتغالُ عن أندونيسيا، ولكنَّ هولندا لم تكن أحسنُ حالًا من سلَفِها؛ فالصليبيون هم الصليبيون، فانقضُّوا على الجزر الأندونيسية سلبًا ونهبًا وقتلًا، ثم بدأت المعاركُ بينهم وبين الممالك الإسلامية، وخاصة متارم، ولكِنَّ أمرَها لم يدُمْ طويلًا؛ حيث بدأت المنافسةُ الإنكليزية تظهر عام 1027، ولكن بعد أن انتهت الحروبُ في أوروبا- وخاصةً بعد انتهاء الحربِ بين إنكلترا وهولندا أيام حروب نابليون- عادت الحكومة الهولندية واستعمرت أندونيسيا؛ حيث كانت إنكلترا قد احتلَّتها بعدها، ثم وقعت معاهدةٌ بين إنكلترا وهولندا تركت إنكلترا بموجِبِها أندونيسيا لهولندا، التي رفعت علَمَها عليها من جديد عام 1232 لكن حدثت عدةُ حروب، منها حروب الأمير المسلم ديبو نيغورو الذي استمَرَّت حروبه مع الهولنديين خمسة أعوام، وحروب بدري الجمعية الخيرية، وحروب آتشيه شماليَّ سومطرة، واستمَرَّت حروبُهم أكثَرَ من ثلاثين سنة، غيرَ الاضطرابات السكانيَّة بين الفَينةِ والأخرى ضِدَّ الهولنديِّين."},{"id":3830,"title":"فتح العثمانيين قلعة أكرى شمال المجر .","date":["العام الهجري :1005","الشهر القمري : صفر","العام الميلادي :1596"],"text":"فتَحَ السلطانُ العثمانيُّ محمد الثالث قلعةَ أكرى في شمال المجر، تمَّ ذلك بعد 18 يومًا من الحصار، وقد قُتِل في هذه المعركة 11 ألف جندي ألماني، وكان العثمانيون قد حاصروا هذه القلعة 39 مرة، لكِنَّهم لم يتمكَّنوا من فتحها سابقًا؛ نظرًا لقوَّةِ تحصينِها."},{"id":3831,"title":"استيلاء الجيش الألماني على مدينة \"يانق قلعة\" .","date":["العام الهجري :1006","الشهر القمري : شعبان","العام الميلادي :1598"],"text":"تقع مدينة \"يانق قلعة\" على بُعد 100 كم في الجنوب الشرقي لفيينا التي فتحها الجيش العثماني سنة 1002، وقد استولى عليها الألمانُ في هذه السنة بطريقة ذكية؛ حيث قامت وحدة تتكلَّمُ التركية بالدخولِ إلى القلعة ومهَّدت الطريقَ لدخولِ الجنود الألمان إلى القلعةِ والسيطرة عليها."},{"id":3832,"title":"ثورة قره يازجي ومعه المرتزقة ضد العثمانيين .","date":["العام الهجري :1009","العام الميلادي :1600"],"text":"بعد أن فرَّ كثيرٌ من الجند من معركة كرزت، قام السلطان العثماني محمد الثالث بنفيهم إلى الأناضول، فقام أحدُهم واسمه قره يازجي وادَّعى أنَّه رأى الرسول صلى الله عليه وسلم في المنام، وأنه وعده بالنصرِ على آل عثمان، فأعلن التمرُّد بعد أن تبِعَه كثيرٌ من المرتزقة من الجنود المنفيِّين، فدخل عينتاب فحاصرته الجيوشُ العثمانية، فأعلن الاستسلامَ على أن يُعطَى ولايةَ أماسيا، فوافق العثمانيون على ذلك، فلما ابتعدت عنه الجيوشُ أظهر العصيانَ ثانيةً وساعده أخوه دلي حسن والي بغداد يومَها، فعاد الجيشُ العثماني بقيادة صقلي حسن باشا فانتصر على قره يازجي الذي توفِّي متأثرًا بجراحه، وجاء أخوه فانتصر على صقلي حسن باشا وقتلَه عام 1010."},{"id":3833,"title":"انتصار الجيش العثماني على الجيش الألماني .","date":["العام الهجري :1010","الشهر القمري : جمادى الأولى","العام الميلادي :1601"],"text":"انتصر الجيشُ العثماني بقيادة حسن باشا على جيش ألماني ضخم مكوَّن من مائة ألف جندي، وقد حاز على غالبية مهمَّات الجيش الألماني الذي كان يحاصر العثمانيين لمدة 69 يومًا في \"قانيجة\" القريبة من يوغسلافيا حاليًّا، ويعدُّ هذا الانتصار من الانتصارات الكبرى التي حقَّقها العثمانيون رغم قلَّة عدد جيشهم!"},{"id":3834,"title":"ثورة الخيالة السباه في إستانبول .","date":["العام الهجري :1011","العام الميلادي :1602"],"text":"قامت ثورة الخيَّالة العثمانيين الذين يسَمَّون بالسباه في إستانبول مطالبين بالتعويضات عما لحِقَ بإقطاعاتهم من أضرارٍ بسبب فتنة الفراريين، ولم يكن بإمكانِ الدولة أن تعطيَهم عِوَضَها لعجزها، فاستعانت عليهم بالانكشارية فقضت على ثورتهم بعد أن أفسَدوا ونهبوا حتى المساجِدَ وغيرها ممَّا وصلت أيديهم إليه!"},{"id":3835,"title":"احتلال الصفويين جزيرة أوال (البحرين) .","date":["العام الهجري :1011","العام الميلادي :1602"],"text":"بدأ النفوذ الإنكليزي يظهر في منطقة الخليج العربي؛ حيث استمالت إنكلترا إليها الشاهَ عباس الصفوي شاه إيران ليقف معها ضد العثمانيين والبرتغاليين، وقد منح الشاه إنكلترا امتيازاتٍ واسعة في التجارة وساعدته هي على مدِّ نفوذه في الخليج، حتى استطاعت قواتُه من احتلال جزيرة أوال (البحرين) في هذا العام، بعد أن كانت تحت السيطرة العثمانية من عام 957 الذين طَرَدوا البرتغاليين منها."},{"id":3836,"title":"نهوض السلطان زيدان السعدي لحرب أخيه أبي فارس في مراكش .","date":["العام الهجري :1012","العام الميلادي :1603"],"text":"لما بايع أهلُ مراكش أبا فارس بن أحمد المنصور الذهبي السعدي، عزم أخوه زيدان على النهوض إليه، فخرج من فاس يؤمُّ بلاد الحوز، واتصل الخبَرُ بأبي فارس فجهَّز لقتال أخيه زيدان جيشًا كثيفًا وأمَّر عليهم ولده عبد الملك، فقيل له: إن زيدان رجلٌ شجاع عارفٌ بمكايد الحرب وخُدَعه، وولدك عبد الملك لا يقدِرُ على مقاومته، فلو سرَّحت أخاك محمد الشيخ المأمون لقتالِه كان أقرب للرأي؛ لأن أهل الغرب لا يقاتلونَه؛ لأنه كان خليفةً عليهم مُدَّةً، فهُم آنَسُ به من زيدان، فأَطلق أبو فارس أخاه المأمونَ من السجن وأخذ عليه العهودَ والمواثيق على النصحِ والطاعة وعدمِ شَقِّ العصا، ثم سرَّحه في ستمائة من جيش المتفرِّقة الذين كان المنصور جمعَهم ليبعث بهم إلى كاغو من أعمال السودان، وقال له ولأصحابه: جِدُّوا السير الليلةَ؛ كي تُصبحوا بمحلة جؤذر على وادي أم الربيع، فلما انتهى الشيخ إلى محلة جؤذر وعلم الناسُ به هُرِعوا إليه واستبشروا بمَقدَمِه، ثم كانت الملاقاةُ بينه وبين السلطان زيدان بموضعٍ يقال له حواتة عند أم الربيع، ففرَّ عن زيدان أكثرُ جيشه إلى المأمون وحنُّوا إلى سالف عهدِه وقديمِ صحبتِه، فانهزم زيدان لذلك، ورجع أدراجَه إلى فاس فتحصَّنَ بها، وكان أبو فارس قد تقدَّم إلى أصحابه في القبضِ على الشيخ متى وقعت الهزيمةُ على زيدان، فلما فر زيدان انعزل الشيخُ فيمن انضمَّ إليه من جيشِ أهل الغرب وامتنع على أصحابِ أبي فارس فلم يقدِروا منه على شيءٍ، وانتعش أمرُه واشتدَّت شوكتُه، ثم سار إلى فاس يقفو أثرَ السلطان زيدان، ولما اتصل بزيدان خبرُ مجيئه إليه راود أهل فاس على القيامِ معه في الحصارِ والذبِّ عنه والوفاء بطاعته التي هي مقتضى بيعتِهم التي أعطَوا بها صفقتَهم عن رضًا منهم، فامتنعوا عليه وقلبوا له ظَهرَ المِجَنِّ، وأعلنوا بنصر الشيخ المأمون وبيعته لقديم صحبتِهم له، ولما آيسَ زيدان من نصرهم وقد أرهقه الشيخُ المأمون في جموعِه، خرج من فاس بحشَمِه وثِقلِه ناجيًا بنفسه وتبِعَه جمعٌ عظيم من أصحاب الشيخ فلم يقدروا منه على شيءٍ، وذهب إلى تلمسان فأقام بها، وأما الشيخ فإنه لما وصل إلى فاس تلقَّاه أهلها ذكورًا وإناثًا وأظهروا الفرحَ بمَقدَمِه، فدخلها ودعا لنفسِه فأجيبَ واستبَدَّ بمُلكِها، ثم أمرَ جيش أهل مراكش أن يرجِعوا إلى بلادهم، فانقلبوا إلى صاحبِهم مُخفِقين."},{"id":3837,"title":"وفاة السلطان المنصور أحمد الذهبي زعيم دولة الأشراف السعديين .","date":["العام الهجري :1012","الشهر القمري : ربيع الأول","العام الميلادي :1603"],"text":"هو السلطان أبو العباس المنصور أحمد، المعروف بالذهبي ابن أبي عبد الله محمد الشيخ المهدي بن محمد القائم بأمر الله الزيداني الحسني السعدي، واسطةُ عِقد الملوك الأشراف السعديين، وأحدُ ملوك المغرب الأقصى العِظام. كانت ولادته بفاس سنة 956, وأمُّه الحُرَّة مسعودة بنت الشيخ الأجلِّ أبي العباس أحمد بن عبد الله الوزكيتي، وكانت من الصالحات الخيرات, وكان أبوه المهدي ينبِّه على أن ابنَه أحمد واسطةُ عِقد أولاده. نشأ المنصور في عَفافٍ وصيانة وتعاطٍ للعلم ومُثافنةٍ لأهله عليه، وكانت مخايل الخِلافة لائحةً عليه إلى أن تمَّ أمره. كان طويلَ القامة ممتلئ الخدين واسِعَ المنكبين، تعلوه صفرةٌ رقيقة، أسود الشعر أدعج أكحل ضيِّق البلج، برَّاق الثنايا، حسن الشكل جميل الوجه، ظريف المنزِع لطيف الشمائل. بويعَ له بالحكم بعد وفاة أخيه عبد الملك في معركة وادي المخازن 986. قال الفشتالي: \"لما كانت وقعة وادي المخازن ونصر الله دينَه وكَبَتَ الكفرَ وأهلَه واستوسق الأمرُ للمنصور، كتب إلى صاحب القسطنطينية العظمى، وهو يومئذ السلطان مراد الثالث بن سليم الثاني، وإلى سائر ممالك الإسلام المجاورين للمغرب يعرِّفُهم بما أنعم الله به عليه من إظهارِ الدين وهلاك عَبَدة الصليب واستئصال شأفتِهم، فوردت عليه الأرسالُ من سائر الأقطار مهنئين له بما فتح الله على يدِه، وكان أول من وفد عليه رسولُ صاحب الجزائر ثم تلته أرسالُ طاغية البرتغال، وهو الريكي القائم بأمرهم\" واستمر أحمد المنصور على منهج أخيه في بناء المؤسسات، واقتناءِ ما وصلت إليه الكشوفاتُ العلمية، وتطويرِ الإدارة والقضاء والجيش، وترتيبِ الأقاليم وتنظيمها، وكان أحمد المنصور يتابع وزراءه وكبارَ موظفيه ويحاسِبُهم على عدم المحافظة على أوقات العمل الرسمية، أو التأخير في الردِّ على المراسلات الإدارية والسياسية، وأحدث حروفًا لرموز خاصة بكتابة المراسَلات السريَّة؛ حتى لا يُعرَفَ فحواها إذا وقعت في يد عدوٍّ. توفي المنصور في الدار البيضاء خارجَ فاس فدُفِن فيها، ثم نُقِل إلى مراكش، ثم خلَفَه بعده ابنه زيدان الذي استخلفه والدُه المنصور بعد أن أَيِس من صلاحِ ابنه الكبير محمد الشيخ المأمون."},{"id":3838,"title":"مبايعة زيدان بن أحمد المنصور السعدي بالحكم في مدينة فاس .","date":["العام الهجري :1012","الشهر القمري : ربيع الأول","العام الميلادي :1603"],"text":"لَمَّا توفِّيَ المنصور أحمد الذهبي السعدي وفرَغَ الناس من دفنِه، اجتمع أهلُ الحَلِّ والعقد من أعيان فاس وكبرائها والجمهورِ من جيش المنصور على بيعةِ ولده زيدان، وقالوا إن المنصور استخلفه في حياتِه ومات في حجرِه، وكان ممن تصدى لذلك القاضيان قاضي الجماعة بفاس أبو القاسم بن أبي النعيم، والقاضي أبو الحسن علي بن عمران السلاسي, وكان زيدان لما توفِّي والده كتم موتَه وبعث جماعةً للقبض على أخيه محمد الشيخ المأمون المسجون بمكناسة، فمنعهم من ذلك الباشا جؤذر كبير جيش الأندلس، وحُمل محمد الشيخ موثقًا إلى مراكش حتى دُفِع إلى أخيه أبي فارس، وكان شقيقًا له فلم يزل مسجونًا عنده إلى أن أخرجه أبو فارس ليقاتِلَ به أخاهما زيدان، وقيل: إن زيدان لما اشتغل بدفنِ والده احتال القائد أبو العباس أحمد بن منصور العلج، فذهب بنصف المحلةِ إلى مراكش نازعًا طاعتَه عن زيدان إلى أبي فارس، ومرَّ في طريقه بمكناسة فأخرج محمد الشيخ من اعتقالِه واحتمله معه إلى أبي فارس، فسجنه فلم يزل مسجونًا عنده."},{"id":3839,"title":"انحراف أهل مراكش عن طاعة زيدان بن المنصور أحمد السعيدي .","date":["العام الهجري :1012","الشهر القمري : ربيع الأول","العام الميلادي :1603"],"text":"كان المنصور أحمد السعيدي قد فرَّق عمالات المغرب على أولادِه، فاستعمل محمد الشيخ المأمون على فاس والغرب وولَّاه ولاية العهد من بعده، واستعمل زيدان على تادلا وأعمالها، واستخلفه عند نهوضه إلى فاس؛ للقضاء على ثورة ابنه الشيخ المأمون، وعيَّن ابنه أبي فارس على مراكش وأعمالها, فلما بلغ أهل مراكش وفاةُ المنصور وكتب إليهم أهلُ فاس بمبايعتهم لزيدان، امتنعوا وبايعوا أبا فارس لكونه خليفةَ أبيه بدارِ مُلكه التي هي مراكش، ولأن جلَّ الخاصة من حاشية أبيه كان يميلُ إلى أبي فارس؛ لأن زيدان كان منتبِذًا عنهم بتادلا سائر أيام أبيه، فلم يكن لهم به كثيرُ إلمام ولا مزيدُ استئناسٍ، مع أنه كان جديرًا بالأمر؛ لعلمه وأدبه وكمال مروءته, فلما شقَّ أهل مراكش العصا على زيدان صدرت فتوى من قاضي فاس ابن أبي النعيم ومفتيها أبي عبد الله القصَّار تتضمن التصريحَ بحديث (إذا بويعَ خليفتان فاقتلوا الآخَرَ منهما) وكانت بيعة أبي فارس بمراكش يوم الجمعة أواخر ربيع الأول من هذه السنة، وهو شقيق الشيخ المأمون، أمُّهما أم ولد اسمها الجوهر، ويقال الخيزران. واسمُ أبي فارس هذا عبد الله وتلقب بالواثق بالله، وكان أكولًا عظيم البطن مصابًا بمس الجن."},{"id":3840,"title":"بدء الحرب العثمانية والإيرانية .","date":["العام الهجري :1012","الشهر القمري : جمادى الآخرة","العام الميلادي :1603"],"text":"بدأت الحربُ العثمانية الإيرانية بعد فترة من الصلح دامت 13 عامًا، وكان هدفُ الصفويين هو استردادَ المدن والأماكن التي استولى عليها العثمانيون، مثل تبريز وأذربيجان."},{"id":3841,"title":"وفاة السلطان العثماني محمد الثالث بن مراد الثالث .","date":["العام الهجري :1012","الشهر القمري : رجب","العام الميلادي :1603"],"text":"هو السلطان محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن يزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد جلبي بن بايزيد الأول بن مراد الأول بن أورخان بن الغازي عثمان، السلطانُ العثماني الثالثَ عشر من سلاطين العثمانيين، ولِدَ في ذي القعدة سنة 974, وكانت والدتُه جاريةً بندقيةَ الأصلِ أحبَّها والده فاصطفاها زوجةً له. أمَّره أبوه على مغنيسا في أواخر سنة 991 ودام واليًا بها إلى موت والده، فجلس مكانه سنة 1003, وقد افتُريَ عليه أنَّه بدأ حكمه بقتل تسعة عشر أخًا من إخوته الذكور. كان السلطان في بداية حكمِه قد ترك إدارةَ الدولة لوزرائه, فأثَّرَ هذا في قوَّة الدولة فضَعُفت داخليًّا وتعرَّضت لعدة هزائم من خصومِها في الخارج، فنصحه عددٌ من العلماء بقيادة جيوش الدولة، فتولى قيادة غالبِ معاركها فدَبَّ في جيشِه الحميَّةُ والغيرة، ففتح قلعةَ أراو الصعبة التي عجز جدُّه السلطان سليمان القانوني عن فتحِها على الرغم من قوَّته وقوة دولته في حينها، كما قابل قواتِ السلطان محمد الثالث التحالفُ النمساوي المَجَري المعادي للدولة العثمانية في معركة كرزت، فحطَّمها ودمرها. حدث في عهده تمرُّدان؛ الأول: ثورة الفرارين، وهم الذين فرُّوا أثناء معركة كرزت، فأمر السلطان بنفيهم إلى الأناضول فتمردوا على الدولة أكثَرَ من مرة, والثورة الأخرى: ثورة الخيالة (السباه) في إستانبول، ثاروا بسبب عجز الدولة عن تعويضِهم عمَّا فقدوه من ريع أملاكِهم أثناء ثورة الفرارين في الأناضول. كان السلطان محمد الثالث سلطانًا وقورًا وجيهًا مَهيبًا صالحًا عابدًا سخيًّا، مخلِصًا عدلًا. وله من الأولاد الذكور سليم خان مات في رمضان سنة 1005 ومحمود خان قتله أبوه في ذي الحجة سنة 1011 وأحمد خان وارثه، بعد أن أخمد الحركاتِ التمردية، والثورات العنيفة، وقاد الجيوشَ بنفسه، وكانت وفاته في نهار الأحد الثامن عشر من رجب من هذه السنة، ومدة حكمه تسع سنين وشهران ويومان، وله من العمر ثمانٍ وثلاثون سنة، وتولَّى بعده ابنه أحمد الأول الذي تولى الحكم وعمره 14 سنة ولم يجلسْ أحد قبلَه من سلاطين العثمانيين في هذه السنِّ على العرش، ثم أبقى أخاه مصطفى محجوزًا مع الجواري والخَدَم بدلَ قتلِه."},{"id":3842,"title":"انتصار العثمانيين على النمساويين .","date":["العام الهجري :1013","العام الميلادي :1604"],"text":"عيَّن السلطانُ أحمد لالا محمد باشا صدرًا أعظم خليفةً للصدر الأعظم يمشجي حسن باشا، حيث كان سردارًا عامًّا للجيوش التي جاهدت في النمسا، وهو من خيرة قوَّاد الجيوش، فاهتمَّ بتقوية الجيوش العثمانية وحاصر قلعةَ استراغون وفتحها، كما حارب إماراتِ الأفلاق والبغدان والأردل، وعقد صلحًا معهم، ولما مات لالا باشا خلَفَه قبوجي مراد باشا صدرًا أعظم، وكان قائدًا لإحدى فرق الجيش، وقد نجحت الجيوشُ العثمانية في هزيمة النمسا واسترداد القلاع الحصينة من مدن يانق واستراغون وبلغراد وغيرها، كما نجحت الجيوشُ العثمانية في جهادِها بالمجر وهزمت النمسا هناك، ونجم عن ذلك قبول النمسا بطلب الصلحِ ودفعِ جزية للدَّولة العثمانية مقدارها مائتا ألف دوكة من الذهب، وبقيت بلادُ المجر بموجِب هذه المعاهدة تابعةً للدولة العثمانية."},{"id":3843,"title":"الدولة العثمانية تجدد الامتيازات للدول الأوربية .","date":["العام الهجري :1013","العام الميلادي :1604"],"text":"جدَّدت الدولةُ العثمانية امتيازاتِ فرنسا وإنجلترا، على مثلها، كما جَدَّدت الاتفاقيةَ مع بولونيا- بولندا- بحيث تمنعُ الدولة تتارَ القرم من التعدي على بولونيا، وتمنع بولونيا القوزاق من التعدِّي على الدولة العثمانية، وتحصَّلت هولندا على امتيازات واستغلت ذلك في نشرِ الدُّخَان داخِلَ ديار الإسلام، وبدأ تعاطيه من قِبَل الجنود، فأصدر المفتي فتوى بمَنعِه فهاج الجندُ وأيَّدَهم الموظَّفون، فاضطر العلماءُ إلى السكوتِ عنه، وهكذا أصبح الجندُ ينقادون خلفَ شهواتهم ويعتَرِضون على العلماءِ."},{"id":3844,"title":"وفاة السلطان جلال الدين محمد أكبر بن همايون التيموري في الهند .","date":["العام الهجري :1014","الشهر القمري : جمادى الآخرة","العام الميلادي :1605"],"text":"هو السلطانُ المؤيَّد المظفَّر أبو الفتح جلال الدين محمد أكبر بن همايون بن بابر التيموري الكوركاني، أكبرُ ملوك الهند وأشهرُهم في الذِّكر، ولِدَ في قلعة أمركوث من أرض السِّند في ثاني ربيع الأول سنة 949هـ من \"حميده بانو\". حين انهزم والده همايون من شير شاه، ثم رجع بعد بضعة سنين فافتتح قندهار وكابل وأكثر بلاد الهند، فلما مات همايون جلس ولدُه جلال الدين على سريره تحت وصاية الوزير بيرم خان؛ لأن سنَّه حينئذ نحو ثلاث عشرة سنة، ولما بلغ أكبرُ أشُدَّه استقَلَّ بالملك، وسافر إلى الحرمين الشريفين، ثم افتتح أمره بالعدل والسخاء، وقرَّب إليه أهل العلم والصلاح، وكان يستمع الحديث، وبنى مساجد وزوايا له، وبنى مدينة بأرضه وجعلها عاصمة بلاد الهند، وبنى بها قصرًا وسماه (عبادت خانه) وقسَّمه على أربعة منازل وأمر أن يجتمع فيه علماء البراهمة والنصارى والمجوس وأهل الإسلام، فيجتمعون في ذلك القصر ويتباحثون في الخلافيات بحضرة السلطان، حتى دخل في مجلسه من أهل الشبهات والشهوات كأبي الفيض وصنوه أبي الفضل والحكيم أبي الفتح ومحمد اليزدي، فجعلهم فريقًا لأهل الصلاح فدسُّوا في قلبه أشياء ورغَّبوه عن أهل الصلاح وقالوا: لا ينبغي للسلطان أن يقلِّدَ أحدًا من الفقهاء المجتهدين، فانشرح صدر السلطان، وفتح أبواب الاجتهاد، فجوَّز متعة النساء، ونكاحَ المسلم بالوثنية، حتى اجترأ على الطعن والتشنيع على السلف الصالح، لا سيما الخلفاء الراشدين، والأئمة المهديين، وأمر بإخراج المشائخ والعلماء من الهند، واجتمع لديه شِرذمة من علماء الوثنيين والنصارى والمجوس ومن أحبار الهنود ومن الشيعة، وكان كل واحد منهم يجتهد أن يرغِّبَه إلى مذهبه، وكانت تحته طائفة من الأميرات الوثنيات بنات ملوك الهند، وصار حوله من يزيِّن له عبادة الأصنام، وتعظيم النار والشمس، فتدرج في الاجتهاد وترقى من الفروع إلى الأصول، وقال بخلق القرآن، واستحالة الوحي، والتشكيك في النبوات، وأنكر الجن، والمَلَك، والحشر والنشر، وسائر المغيبات، وأنكر المعجزات، وجوز التناسُخ، وحرَّم ذبح البقرة، وحطَّ الجزية عن أهل الذمة، وأحلَّ الخمر والميسِر والمحرَّمات الأُخر، وأمر بإيقاد النار في حَرَمِه على طريق المجوس، وأن يعظِّم الشمس وقت طلوعه على طريق مشركي الهند، وقرَّر أن الحق دائر بين الأديان كلها، فينبغي أن يُقتَبَس من كلها أشياء، وكان يسجد للشمس والنار في كل سنة يوم النيروز بالإعلان، وشرع ذلك من سنة خمس وعشرين الجلوسية، ورسم القشقة على جبينه يوم العيد الثامن من شهر سنبله، وربط سلكًا من الجواهر عن أيدي البراهمة تبركًا، وكذلك كان يفعل كلَّ ما يفعله كفار الهند، ويستحسنه ويحرِّض أصحابه على ما فعله، ويحثهم على ترك التقليد، يعني به دين الإسلام، ويهجِّنه ويقول: إن واضِعَه فقراء الأعراب، وأمر أن لا يقرأ من العلوم العربية غير النجوم والحساب والطب والفلسفة، فكان هذا الدين الذي اخترعه مصدرَ كراهيةٍ شديدة له في نفوس أهل الإسلام، حتى انتهى الأمر بهم مرَّةً إلى شق عصا الطاعة علنًا، بل قيل: إن ابنه الأمير جهانكير ثار عليه وأخذ يدبِّر له المكائدَ خُفْية، فحشد جهانكير جيشًا من ثلاثين ألف فارس، وقتل \"أبا الفضل\" مؤرِّخَ القصر وأحبَّ الأصدقاء إلى نفس أبيه، فحَطَّمت قوَّته النفسيَّة وتنكَّر له أبناؤه في أواخر أيامه، ومات الملك أكبر في سكندر آباد قريب آكره، بعد أن حكم أربعين سنة، مات بمرض الديسنتاريا، وقيل: مات مسمومًا بتدبير ابنه جهانكير، ولم يجد من يصلِّي عليه من أنصار أيَّةِ عقيدة أو مذهب ممَّن جمعهم حوله. وفي مطلع القرن العشرين الميلادي عملت إنجلترا على تشجيع مرزا غلام أحمد القادياني في الهند على إحياء ما دعا إليه الملك المغولي جلال الدين محمد أكبر!!"},{"id":3845,"title":"تولي السلطان جهانكير خان بن أكبر الحكم في الهند .","date":["العام الهجري :1014","الشهر القمري : جمادى الآخرة","العام الميلادي :1605"],"text":"تولى السلطانُ أبو الفتح نور الدين محمد جهانكير خان بن جلال الدين أكبر المغوليُّ- من سلالة تيمورلنك- الحُكمَ في الهند، بعد وفاة والده، وفي عهده بدأت القوى الاستعمارية تتطلَّعُ إلى السيطرة على الهند تحت اسم التجارة، وقد دام حكمُه ثلاثًا وعشرين سنة."},{"id":3846,"title":"وفاة الشيخ ملا علي القاري الحنفي .","date":["العام الهجري :1014","الشهر القمري : شوال","العام الميلادي :1606"],"text":"هو الشيخ نور الدين أبو الحسن علي بن سلطان بن محمد القاري، الهَرَوي المكي، المعروف بملَّا علي القاري، من فقهاء الحنفية، وُلِد في هراة وسكن مكةَ وتوفي بها. كان زاهدًا في الدنيا، بعيدًا عن الحكَّام ومجالِسِهم، مُعرِضًا عن الوظائف والأعمال، وكان شديدًا عليهم، حاملًا على أهلِ البدع والضلالات في مكَّة محلِّ إقامته، قانعًا بما يحصِّل من بيعِ كُتُبِه، ويغلِبُ على حاله الزهد والعفاف والرضا بالكفاف، وكان قليلَ الاختلاط بغيره. له مصنفات عديدة، منها: الأسرار المرفوعة في الأخبار الموضوعة، الموضوعات الكبرى، وجمع الوسائل في شرح الشمائل، وشرح مسند أبي حنيفة، وشرح نُخبة الفِكَر في مصطلحات أهل الأثر، ومرقاة المفاتيح شرح مشكاة المصابيح، وشرح الشفا للقاضي عياض، وغيرها من الكتب. توفي بمكَّة ودفن بمقبرة المُعَلاة."},{"id":3847,"title":"معاهدة ستفاتوروك بين الدولتين العثمانية والنمساوية .","date":["العام الهجري :1015","الشهر القمري : رجب","العام الميلادي :1606"],"text":"تم توقيعُ معاهدة بين الدولتين العثمانية والنمساوية، عُرفت باسم معاهدة ستفاتوروك، وانتهت بها تلك الحربُ التي استمرت نحو ثلاث عشرة سنة ونصف السنة. وبمقتضى هذه المعاهدة دفعت النمسا إلى الدولة العثمانية غرامةَ حرب قدرها 67000 سكة ذهبية، وأُلغيت الجزيةُ التي كان يدفعُها إمبراطور النمسا إلى الدولة العثمانية كلَّ سنة، وثبتت الحدودُ على أساس أن لكلٍّ الأراضيَ الموجودةَ تحت سيطرته، وأنْ تخاطِبَ الدولةُ العثمانية حاكمَ النمسا باعتباره إمبراطورًا لا ملِكًا، يقفُ على قدمِ المساواة مع السلطانِ العثماني"},{"id":3848,"title":"نهوض عبد الله بن الشيخ المأمون لحرب عمه أبي فارس .","date":["العام الهجري :1015","الشهر القمري : شعبان","العام الميلادي :1606"],"text":"دعا الشيخ المأمون ابن السلطان أحمد المنصور السعدي تجارَ فاس فاستسلف منهم مالًا كثيرًا وأظهر من الظلمِ وسوءِ السيرة وخُبث السريرة ما هو شهيرٌ به، ثم تتبَّع قوَّاد أبيه فنهب ذخائِرَهم واستصفى أموالَهم وعذَّب من أخفى من ذلك شيئًا منهم، ثم جهز جيشًا لقتال أخيه أبي فارس بمراكش، وكان عدد الجيش نحو الثمانية آلاف، وأمَّرَ عليه ولده عبد الله فسار بجيوشه فوجد أبا فارس بمحلتِه في موضع يقال له إكلميم، ويقال في مرس الرماد، فوقعت الهزيمةُ على أبي فارس وقُتِل نحو المائة من أصحابِه ونُهِبت محلتُه، وفرَّ هو بنفسه إلى مسفيوة، ودخل عبد الله بن الشيخ مراكش فأباحها لجيشه، فنهبت دورَها واستبيحت محارمَها واشتغل هو بالفساد، ومن يشابِهْ أباه فما ظلم!! حتى حُكِي أنَّه زنى بجواري جدِّه المنصور واستمتع بحظاياه، وأكل في شهر رمضان وشَرِب الخمرَ فيه جِهارًا، وعكف على اللذات، وألقى جلباب الحياء عن وجهه، وكان دخولُه مراكش في العشرين من شعبان من هذه السنة."},{"id":3849,"title":"طرد المسلمين من أسبانيا (الأندلس). .","date":["العام الهجري :1016","العام الميلادي :1607"],"text":"أصدرت الحكومةُ الأسبانية مرسومًا يقضي بترحيل المسلمين من إسبانيا ترحيلًا نهائيًّا."},{"id":3850,"title":"ثورة محمد بن عبد المؤمن المهدي ثم هزيمته من السلطان زيدان .","date":["العام الهجري :1016","الشهر القمري : شوال","العام الميلادي :1608"],"text":"لما دخل عبدُ الله بن الشيخ المأمون السعدي مراكشَ واستولى عليها فعَلَ فيها أعظَمَ من فعلته الأولى بفاس، فهربت شرذمة من أهل مراكش إلى جبل جيليز واجتمع هنالك منهم عصابةٌ من أهل النجدة والحمية، واتفق رأيُهم على أن يُقَدِّموا للخلافة محمدَ بن عبد المؤمن ابن السلطان محمد الشيخ، وكان رجلًا خيِّرًا ديِّنًا صيِّنًا وقورًا, ومن أحفاد السلطان محمد الشيخ المهدي السعدي، فبايعه أهل مراكش هنالك والتفوا عليه، فخرج عبد الله بن الشيخ لقتال مَن بجبل جيليز والقبض على أميرهم ابن عبد المؤمن، ولما التقى الجمعان انهزم عبد الله وولى أصحابُه الأدبار فخرج من مراكش مهزومًا سادس شوال من هذه السنة، وترك محلَّتَه وعدتَه وجلَّ جيشه، وأخذ على طريق تامسنا، وامتُحِن أصحابُه في ذَهابِهم حتى كان مُدُّ القمح عندهم بثلاثين أوقية والخبزة من نصف رطل بربع مثقال، ولم يزل أصحابه ينتَهِبون ما مرُّوا عليه من الخيام والعمود ويَسْبُون البناتِ إلى أن وصلوا إلى فاس في الرابع والعشرين من شوال، وأما محمد بن عبد المؤمن فإنَّه لما دخل مراكش واستولى عليها صفَحَ عن الذين تخلَّفوا بها من أهل المغرب من جيش عبد الله بن الشيخ، وأعطاهم الراتب فلم يعجِبْ ذلك أهلَ مراكش ونقَموا عليه إبقاءه عليهم، وكانوا نحو الألف ونصف فكتبوا سرًّا إلى السلطان زيدان بالجبل فأتاهم وخيَّم نازلًا بظاهر البلد فخرج محمد بن عبد المؤمن إلى لقائِه فانهزم ابن عبد المؤمن ودخل السلطان زيدان مراكش واستولى عليها وصفح هو أيضًا عن الفئة المتخلِّفة عن عبد الله بن الشيخ!!"},{"id":3851,"title":"استيلاء السلطان زيدان على فاس وفرار أخوه محمد الشيخ .","date":["العام الهجري :1017","الشهر القمري : ذي القعدة","العام الميلادي :1609"],"text":"كان محمد الشيخ المأمون بن أحمد المنصور الذهبي السعدي ما يزال على قُبحِ السيرة والإساءة إلى الخاصة والعامة، حتى ملَّتْه النفوسُ ورفضته القلوبُ وضاق أهلُ فاس بشؤمِه ذرعًا، وكان قد بعث ابنَه عبد الله مرةً ثالثة إلى حرب أخيه السلطان زيدان بمراكش وأعمالها، فخرج عبد الله من فاس آخِرَ ذي الحجة سنة 1016 فالتقى الجمعان بوادي بوركراك، فكانت الهزيمة على عبد الله وفرَّ في رهطٍ من أصحابه وترك محلَّتَه بما فيها بيَدِ السلطان زيدان، فاستولى عليها وانضَمَّ إليه جيش عبد الله من أهل فاس وغيرهم ميلًا إليه ورغبةً في صحبته، فعفا عنهم وتألَّفَهم، واستفحل أمرُ السلطان زيدان وتكلَّم به أهل فاس وسائِرُ بلاد الغرب، واتصل الخبر بالشيخ المأمون، وعرف أن قلوب الناس عليه فخاف الفضيحةَ وأصبح غاديًا في أهله وحشمه إلى ناحية العرائش مستصرخًا بالطاغية الإصبنيول في الأندلس على السلطان زيدان، وحمل معه أمه الخيزران وبعض عياله وجماعة من قواده وبطانته، وذلك في ذي القعدة سنة 1017، لكن الطاغيةَ لم يُمِدَّه بشيء, وانتهى مصطفى باشا قائد زيدان إلى القصر الكبير فقبض على من وجَدَ به من أصحاب الشيخ، وفر عبد الله وأبو فارس فنزلا بموضعٍ يقال له سطح بني وارتين، فبلغ خبرهما إلى السلطان زيدان، فجاء حتى نزل قبالتَهما بموضعٍ يقال له آرورات، ففَرَّ من كان معهما إلى السلطان زيدان، ولَمَّا بقِيا أوحشَ مِن وتِدٍ بقاعٍ، فرَّا إلى دار اليهودي ابن مشعل من بلاد بني يزناسن فأقاما بها."},{"id":3852,"title":"الأمير فخر الدين المعني يستولي على بعلبك ويهدد باحتلال دمشق .","date":["العام الهجري :1018","العام الميلادي :1609"],"text":"فخرُ الدين المعني الثاني هو حفيد فخر الدين المعني الأول، الدرزي الأصل الذي قاتل مع السلطان سليم، فتولى بذلك لبنان والجبال المحيطة به، ولما تولى هذا الحفيدُ السلطة في لبنان عام 999هـ وكان درزيًّا وصوليًّا كبيرًا واستطاع أن يجمع المُعادين للإسلام من نصارى ونُصيرية ودروز، وأمثالهم، حتى تمكَّن من جبال لبنان، والسواحل وفلسطين، وأجزاء من سورية، ولما قوِيَ أمره فاوض الطليان فدعموه بالمال وبنى القلاع والحصون، وكوَّن لنفسه جيشًا زاد على الأربعين ألفًا، ثم أعلن الخروجَ على الدولة العثمانية عام 1022هـ غيرَ أنه هُزم وفرَّ إلى إيطاليا، وكان قد تلقَّى الدعم من إمارة فلورنسا الإيطالية، ومن البابا، ورهبان جزيرة مالطة (فرسان القديس يوحنا)، وقد عاد فخر الدين إلى لبنان بعد أن أصدر السلطانُ فرمانًا بالعفو عنه واندفع لتغريب البلادِ، ثم أعلن التمردَ من جديد مستغلًّا الحرب العثمانية الصفوية الشيعية، ولكنه فشِلَ وأُسِر وسيقَ إلى إستانبول، ثم اندلعت الثورة عام 1045هـ ولكنه هذه المرة أُسِر وشُنِق، وفَشِلت الحركة المسلَّحة التي قادها ابن أخيه ملحم للأخذِ بثأره."},{"id":3853,"title":"وفاة السلطان أبي فارس بن أحمد المنصور الذهبي السعدي .","date":["العام الهجري :1018","الشهر القمري : جمادى الأولى","العام الميلادي :1609"],"text":"هو السلطان أبو فارس عبد الله بن المنصور أحمد السعدي، بويع بمراكش بعد وفاة والده، ثم بعث أخاه محمد الشيخ المأمون لقتال أخيهما السلطان زيدان، فلما انتصر عليه نكث محمد الشيخ عهده مع أخيه أبي فارس واستبدَّ عليه، ثم بعثَ إليه ابنَه عبد الله فهزَمَ عمَّه أبا فارس إلى مسفيوة ثم منها إلى السوس، فأقام عند حاجب أبيه عبد العزيز بن سعيد الوزكيتي، ثم لما بالغ زيدان في طلبه فرَّ إلى أخيه الشيخ المأمون فلم يزل مع ابنه عبد الله بن الشيخ إلى أن قُتل مصطفى باشا ودخل عبد الله فاس، فاستولى عليها فاتَّفق رأي قوَّاد شراكة على قتل عبد الله وتولية عمِّه أبي فارس، فبلغ ذلك عبد الله فدخل على عمِّه أبي فارس ليلًا مع حاجبه حمو بن عمر فوجده على سجادتِه وجواريه حوله فأخرجهنَّ وأمر بعمِّه فخُنِق وهو يضربُ برجليه إلى أن مات."},{"id":3854,"title":"استيلاء النصارى الأسبان على العرائش بخيانة الشيخ ابن السعدي .","date":["العام الهجري :1019","الشهر القمري : رمضان","العام الميلادي :1610"],"text":"استولى النصارى الأسبان على العرائش، وذلك بعد إخراجهم للمسلمين منها باتفاق مع حاكمها الشيخ المأمون ابن المنصور السعدي، الذي استعان بهم على أخيه السلطان زيدان، فاشترطوا عليه وقتها إعطاءهم العرائش وإخلاءها من سكَّانها، ففعل- خذَلَه اللهُ- ولما خرج منها المسلمون أقام بها القائد الكرني إلى أن دخلها النصارى واستولوا عليها في رابع رمضان من هذه السنة، ووقع في قلوب المسلمين من الامتعاض لأخذ العرائش أمرٌ عظيم، وأنكروا ذلك أشدَّ الإنكار، وقام الشريف أبو العباس أحمد بن إدريس العمراني ودار على مجالس العلم بفاس، ونادى بالجهاد والخروج لإغاثة المسلمين بالعرائش، فانضاف إليه أقوامٌ وعزموا على التوجه لذلك، ففَتَّ في عَضُدِهم قائدُهم حمو المعروف بأبي دبيرة وصرف وجوههم عما قصدوه في حكايةٍ طويلةٍ، وكان الشيخ المأمون لما خاف الفضيحةَ وإنكار الخاصة والعامة عليه إعطاءه بلدًا من بلاد الإسلام للكفَّار، احتال في ذلك وكتب سؤالًا إلى علماء فاس وغيرها يذكُرُ لهم فيه أنه لَمَّا وغل في بلاد العدو الكافرِ واقتحمها كرهًا بأولاده وحشَمِه، منعه النصارى من الخروج من بلادِهم حتى يعطيَهم ثغر العرائش وأنَّهم ما تركوه خرج بنفسِه حتى ترك لهم أولادَه رهنًا على ذلك، فهل يجوز له أن يفدِيَ أولاده من أيدي الكفار بهذا الثغرِ أم لا؟ فأجابوه: بأن فداء المسلمين سيما أولاد أمير المؤمنين سيما أولاد سيد المرسلين صلَّى الله عليه وسلم من يد العدو الكافر بإعطاء بلدٍ من بلاد الإسلام له- جائزٌ، وإنا موافقون على ذلك، ووقَّع هذا الاستفتاء بعد أن وقع ما وقع، وما أجاب من أجاب من العلماء عن ذلك إلا خوفًا على نفسه، وقد فرَّ جماعة من تلك الفتوى، كالإمام أبي عبد الله محمد الجنان صاحب الطرر على المختصر، وكالإمام أبي العباس أحمد المقري التلمساني مؤلف نفح الطيب، فاختفيا مدةً استبراءً لدينهما حتى صدرت الفتوى من غيرهما، وبسبب هذه الفتوى أيضًا فرَّ جماعة من علماء فاس إلى البادية، كالشيخ أبي علي الحسن الزياتي شارح جمل ابن المجراد، والحافظ أبي العباس أحمد بن يوسف الفاسي، وغيرهما."},{"id":3855,"title":"وفاة الفقيه أحمد بن يحيى بن سالم الذويد اليمني .","date":["العام الهجري :1020","الشهر القمري : جمادى الأولى","العام الميلادي :1611"],"text":"هو الشيخُ الفقيه المحقِّق أحمد بن يحيى بن سالم الذويد بن على بن محمد بن موسى الصعدي اليمني، أخذ عن السيد محمد بن عز الدين المفتي، وعبد العزيز بن محمد بن بهران، وسمع الأمهَّات الستَّ، واستجاز فيها من الحافظ محمد بن محمد المصري, وأجلُّ تلامذة الفقيه أحمد الذويد: الإمامُ القاسم بن محمد، والفقيه مهدي الشعيبي، وغيرهما, وكان فقيهًا محدِّثًا قليل النظير في المعقولات والصفات، إمامًا في الشرعيات على الإطلاق، وكان آيةً من آيات الله، وله في كل علم قدَمٌ راسخة، وبلغ في علمِ الطبِّ والرمل وحل السحر وغيرها مبلغًا عظيمًا، وقرأ في التوراة، وكان من أهل الثروة والمال، واجتمع له من الكتُبِ خزانة ملوكية مع مكارم أخلاق، وتوفِّيَ بصَعدة."},{"id":3856,"title":"هزيمة العثمانيين أمام الصفويين وابتلاء أهل السنة في العراق .","date":["العام الهجري :1021","العام الميلادي :1612"],"text":"استغَلَّ الشاه عباس الصفوي انشغالَ الدولة العثمانية بالثورات الداخلية والحروب مع أوربا، بالإضافة للضعف الذي دبَّ فيها، فباشر في تخليصِ عراق العجم, واسترجع شمالَ العراق وتبريز ووان، واستطاع أن يحتلَّ بغداد والأماكن المقدَّسة الشيعية في النجف وكربلاء والكوفة، وكانت الجيوشُ العثمانية أضعفَ من أن تقاوم الجيوشَ الصفوية، فاضطر السلطان العثماني أحمد الأول أن يعقِدَ صلحًا مع الصفويين في عام 1013هـ استرجع فيه الصفويون كلَّ المناطق التي كان قد ضَمَّها السلطان سليمان القانوني، بما في ذلك بغداد، وكان هذا بداية التراجع للدولة العثمانية. وقد زارها الشاه عباس الصفوي وسَطَ مظاهر الإجلال والتقديس، وقد أورد بعضُ المؤرخين أنه قضى عشرة أيام في زيارته للنجف؛ حيث قام بنفسِه بخدمة الحُجَّاج في ذلك المكان، كما يذكرون أيضًا أنَّه إمعانًا في إعلان تمسُّكِه بالمذهب الشيعي وولائِه للرفض، وعلى الرغمِ من تعصُّبه الشديد للمذهب الشيعي إلَّا أنه رفع أيدي رجال الدينِ عن التدخُّل في شئون الحكم والسياسة، ومارس نوعًا من السلطة المُطلَقة في حكم البلاد، وقد أنزل الشاه عباس الصفوي أقسى أنواعِ العقاب بالسنَّة الذين يعتبرهم أعداءً للدولة، فإما أن يُقتَلوا أو تُسمَل عيونُهم، ولم يكن يتسامحُ مع أيٍّ منهم إلا إذا تخلى عن مذهبِه السني وأعلن ولاءه للمذهب الشيعي، واضطرت الدولةُ العثمانية نتيجةً لمعاهدة مع الصفويين أن تترك للدَّولة الصفوية الرافضية الشيعية جميعَ الأقاليم والبلدان والقلاع والحصون التي فتحها العثمانيون في عهد السلطان الغازي سليمان الأول بما فيها مدينة بغداد! وهذه أول معاهدة تركت فيها الدولةُ بعضَ فتوحاتِها، وكانت فاتحةَ الانحطاط والضَّعفِ، وأوَّلَ المعاهدات التي دلَّت على ضعف الدولة العثمانية! لقد بالغ الشاه عباس الصفوي في عدائه للمذهب السُّني، وإمعانًا في ضرب الدولة العثمانية حاميةِ المذهب السنِّي اتصل بملوك النصارى، وعقَدَ اتفاقات تعاوُن مشترك معهم؛ من أجلِ تقويض أركان الدولة العثمانية السُّنية، وقدَّم العديد من التنازلات لهذه الدول الأوروبية النصرانية تأكيدًا لتعاونِه معهم انطلاقًا من عدائِه للدولة العثمانية، وعامل الشاه عباس الصفوي النصارى في إيران معاملةً حسنةً على عكس معاملته لأهل السنَّة، وقد كان لمعاملته المتميِّزة للنصارى أن نشِطَت الحركة التنصيرية في إيران، كما شجع التجار الأوربيين في عقد صفقات تجارية كبيرة مع التجَّار في إيران، وأصبحت إيران سوقًا رائجًا للتجارة الأوروبية، ثم توَّج تسامحه مع النصارى بأن أعلن في عام 1007هـ أوامِرَه بعدم التعرضِ لهم، والسماح لهم بحرية التجوُّل في ربوع الدولة الصفوية، وأعطاهم امتيازاتٍ ببناء الكنائس في كبرى المدن الإيرانية، وهذه المعاملة للنصارى كانت نكايةً في الدولة العثمانية السُّنِّية!!"},{"id":3857,"title":"وفاة ابن محلي المدعي أنه المهدي المنتظر بفاس .","date":["العام الهجري :1022","العام الميلادي :1613"],"text":"أحمد بن عبد الله السجلماسي أبو العباس المعروف بابن محلي، متصَوِّف ادعى أنه المهدي الفاطمي المنتظَر، ولِدَ بمدينة سجلماسة، وطلب العلم بفاس، تصوَّف وكثُرَ أتباعه، وذهب إلى جنوب المغرب فكاتب رؤساء القبائل وعظماء البلدان أنَّه المهدي الفاطمي المنتظَر، مدَّعيًا أنه من سلالة العباس بن عبد المطلب، وزحف على سجلماسة واستولى عليها بعد قتال، وأرسل السلطانُ زيدان بن أحمد السعدي صاحب المغرب جيشًا لقتاله، فانهزم الجيشُ وقَوِيَ أمر المدَّعي، فزحف على مراكش واستقرَّ بها مَلِكًا تاركًا التصوف والتنسُّك، فهاج عليه يحيى بن عبد الله أحد المتصوِّفة انتصارًا لزيدان السعدي، وجرت بينهما حرب على أبواب مراكش، أصيب ابن محلي فيها برصاصة أردته قتيلًا وعُلِّق رأسُه مع بعض أنصاره على أسوارِ مراكش."},{"id":3858,"title":"وفاة السلطان محمد الشيخ المأمون ابن المنصور أحمد السعدي .","date":["العام الهجري :1022","الشهر القمري : رجب","العام الميلادي :1613"],"text":"هو السلطان أبو عبد الله محمد الشيخ المأمون بن أحمد المنصور الذهبي، ملك السعديين في المغرب الأقصى. كان المأمونُ وَلِيَّ عهد أبيه المنصور وخليفتَه على فاس وأعمالها سائرَ مدة أبيه، وكان للمنصور اعتناءٌ تام به واهتمامٌ بشأنه حتى قيل إن المنصور كان لا يختِمُ على صندوق من صناديق المال إلا قال: \"جعل الله فتحَه على يد ابنِه الشيخ رجاءَ أن يقوم بالأمر بعدَه، فلم يُقدَّرْ له، وخرج الأمرُ عن مرادِه؛ فقد أساء المأمون السيرةَ وأضَرَّ بالرعية، قال اليفرني: \"كان فسيقًا خبيث الطويَّة مُولَعًا بالعبث بالصبيان، مدمنًا للخمر سفاكًا للدماء غير مكتَرِث بأمور الدين من الصلاة وشرائطها، ولَمَّا ظهر فساده وبان للناس عَوارُه، نهاه وزير أبيه القائد أبو إسحاق إبراهيم السفياني عن سوء فعلِه، فلم ينتَهِ واستمر على قبح سيرتِه، فأعاد عليه اللومَ فلَجَّ في مذهبِه، ولما أكثَرَ عليه مِن التقريع سقاه السمَّ فكان فيه حَتفُه, فلما كثرت قبائحُ المأمون وترددت الشكايات لأبيه، كتب إليه لينكَفَّ عن غيِّه وينزجر عن خبثِه، فما زاده التحذيرُ إلا إغراءً، فلما رأى المنصور أنه لم يكترثْ بأمرِه ولم ينزجِرْ عن قبائحه، عزم على التوجُّه إلى فاس بقصد أن يمكُرَ به ويؤدِّبَه بما يكون رادعًا له، فلما سمع الشيخ بذلك جمع عساكِرَه وهيأَ جنده لمدافعة أبيه، فتحيَّل عليه أبوه حتى أسَرَه ثم سجنه في مكناسة، وظل في سجنِه حتى أخرجه أخوه أبو فارس ليحارِبَ به أخاهما زيدان، وتمكن الشيخ وتغلب على أخيه زيدان، ثم على أبي فارس، وسيطر على حكم المغرب، فظلم الرعيةَ وأسرف على نفسِه إلى أن توفي في هذا العام. بعد تذمُّر وسخَط أهل تطوان ونواحيها من أفعال الشيخ المأمون، اجتمع أعيانُ القوم وتآمروا على قتل الشيخ وأتباعه، فقُتِل السلطان الشيخ المأمون في وسط محلَّتِه المعروفة بفج الفرس, وانتُهِبت تلك المحلة وتفرَّقت جموعه, وتولى بعده أخوه زيدان في حُكم المغرب."},{"id":3859,"title":"وقوع غلاء وموت بمدينة فاس .","date":["العام الهجري :1022","الشهر القمري : ذي الحجة","العام الميلادي :1614"],"text":"وقع غلاءٌ بفاس حتى بيع القمحُ بأوقيتين وربع للمُدِّ، وكثر الموتى حتى إن صاحب المارستان أحصى من الموتى أربعة آلاف وستمائة إنسان من عيد الأضحى إلى ربيع الأول من السنة التي بعدها، وخربت أطرافُ فاس وخلت المداشر- القرى أو المزارع- ولم يبقَ بلَمْطَةَ سوى الوحوشِ."},{"id":3860,"title":"معاهدة ستراتورك بين الدولة العثمانية والنمسا والمجر من جهة أخرى .","date":["العام الهجري :1023","العام الميلادي :1614"],"text":"عقدت الدولةُ العثمانيةُ صلحًا مع النمسا في هذا العام تخلصت فيه النمسا ممَّا كانت تدفعُه من جزيةٍ سنوية للعثمانيين، على أن تدفَعَ مائتي ألف دوكا دفعة واحدة، علمًا أن الجزية السنوية كانت تبلغ ثلاثين ألف دوكا! وذلك بعد الخلافِ على بلاد المجر ومحاولة النمسا إبعادَ أمير المجر عن العثمانيين وإغرائه ليكون ملكًا بمساعدة النمسا، وبقيت المجرُ بعد هذا الصلح تتبع الدولةَ العثمانية."},{"id":3861,"title":"استيلاء النصارى الأسبان على المعمورة المهدية .","date":["العام الهجري :1023","الشهر القمري : جمادى الآخرة","العام الميلادي :1614"],"text":"لما استولى النصارى الأسبان على العرائش، طمحت نفوسُهم إلى الاستيلاء على غيرها وتعزيزِها بأختها، فرأوا أنَّ المهديةَ أقربُ إليها، فبعث إليها الطاغية فيليبس الثالث من جزيرة قادس تسعين مركبًا حربية، فانتهوا إليها واستولوا عليها من غير قتال؛ لفرار المسلمين الذين كانوا بها عنها، وبعدها كتب أهل سلا إلى السلطان زيدان، فبعث إليهم أبا عبد الله العياشي الذي كان مقدمًا بوكالته على الجهاد بدكالة، وأمر أبو عبد الله أهلَ سلا بالتهيؤ للغزو واتخاذ العُدة، فلم يجد عندهم إلَّا نحوَ المائتين منها، وكانت السنون والفِتَن قد أضعَفَتها، فحضَّهم على الزيادة والاستكثار منها، فكان مبلغُ عِدَّتهم بما زادوه زهاءَ أربعمائة، ثم نهض بهم إلى المعمورة فصادف بها من النصارى غِرَّةً، فكانت بينه وبينهم حربٌ قُربُها إلى أن غربت الشمس، فقُتِل من النصارى زهاءُ أربعمائة، ومن المسلمين مائتان وسبعون، وهذه أول غزوة أوقعها في أرض الغرب بعد صدوره من ثغر آزمور، ومنها أقصرت النصارى عن الخروج إلى الغابة، وضاق بهم الحالُ، ثم إن السلطان زيدان لما بلغه اجتماعُ الناس على سيدي محمد العياشي بسلا وسلامته من غدرةِ قائدِه السنوسي، بعث إلى قائده على عسكر الأندلس بقصبة سلا المعروف بالزعروري وأمره باغتيالِه والقبض عليه، ففاوض الزعروري أشياخَ الأندلس في ذلك، فاتفق رأيُهم على أن يكون مع العياشي جماعةٌ منهم عينًا عليه وطليعةً على نيَّتِه واستخبارًا لِما هو عازم عليه وما هو طالبٌ له، فلازمه بعضُهم وشعر العياشي بذلك فانقبض عن الجهادِ ولَزِم بيته."},{"id":3862,"title":"وفاة شيخ الإسلام عمر العرضي الحلبي .","date":["العام الهجري :1024","الشهر القمري : شعبان","العام الميلادي :1615"],"text":"هو محدِّث حلب شيخ الإسلام عمر بن عبد الوهاب العرضي، أوحدُ وقته في فنون الحديث والفقه والأدب، أخذ عن محمود البيلوني، ورضي الدين الحنبلي، وبه تخرج، ومن أفخر أسانيدِه روايتُه عن والده عبد الوهاب عن زكرياء عن ابن حجر، ومن أعظم مؤلفاته \"شرح الشفاء\" في أربعة أسفار ضخامٍ، سماه \"فتح الغفار بما أكرم الله به نبيه المختار\" اشتغل به نحو اثنتي عشرة سنة، وله \"مناهج الوفا فيما تضمنه من الفوائد اسم المصطفى\"، وله معجم كبير، وشرحٌ على ألفية السيوطي في الاصطلاح. كانت وفاته بحلب 16 شعبان."},{"id":3863,"title":"وفاة الإمام الحسن بن علي بن داود المؤيدي .","date":["العام الهجري :1024","الشهر القمري : شوال","العام الميلادي :1615"],"text":"هو الناصر لدين الله الإمام الحسن بن علي بن داود المؤيدي إمام الدولة الزيدية في اليمن. له تبحُّرٌ في علوم عديدة، كالنحو والصرف، والمنطق والمعاني والبيان، والأصول والتفسير، والفقه والحديث، وله رسائل تدلُّ على بلاغته وقوة تصرُّفه، دعا إلى نفسه سنة 984 في نصف شهر رمضان منها، فاجتمعت إليه الزيدية وأجابوا دعوتَه، وبايعوه في بلاد صعدة، وخرج منها بجيش إلى الأهنوم واشتعلت الأرض نارًا بقيامه على الأتراك، ودخل في طاعته بعضُ أولاد الإمام شرف الدين، وأَسَر عبد الله بن المطهر وأودعه السجنَ ثم توجَّه بجند واسع لأخذ بلاد همدان، ففتح أكثرها وخرج الأتراك من صنعاء وأميرُهم سنان، فما زالت الحرب بينهما سِجالًا، وفي سنة 993 افتتح سنان بلاد الأهنوم، وانحصر الإمام الحسن في محل يقال له الصاب، ودُعي إلى السلم فأجاب، وخرج إلى سنان في نصف شهر رمضان منها، وهذا من غرائب الزمان: كونُ قيامه في نصف شهر رمضان، وأسْرُه في نصف شهر رمضان، ثم دخل به سنان إلى صنعاء، فوصل به إلى الباشا حسن فسجنه وقد كان أسَرَ أولاد المطهر بن شرف الدين الأربعة لطف وعلي يحيى وحفظ الله وغوث الدين، وسجنهم مع الإمام الحسن، وفي شهر شوال من هذه السنة أرسل الباشا بهم جميعًا إلى بلاد الترك، وكان آخر العهد بهم، وقد روي أنه مات الإمام الحسن في بلاد الترك محبوسًا في شهر شوال، وله أخبار حسان."},{"id":3864,"title":"وفاة السلطان العثماني أحمد الأول وتولي أخيه مصطفى الأول .","date":["العام الهجري :1026","الشهر القمري : ذي القعدة","العام الميلادي :1617"],"text":"هو السلطان أحمد الأول بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول. ولد في 12 جمادى الثانية سنة 998 (18 ابريل سنة 1590م) تولى السلطنة بعد أبيه ولم يتجاوز سنه الرابعة عشرة إلَّا بقليل, وقام بحجز أخيه مصطفى بين الخدم والجواري. كانت أركانُ الدولة في بداية حكمه غيرَ ثابتة، فنارُ الحرب مستعرة مع النمسا غربًا, ومع الصفويين شرقًا؛ حيث كانت الحرب معهم شديدة الوطأة؛ لتولي الشاه عباس الصفوي قيادتها، مما جعلها أعظمَ من كافة الحروب السابقة, فاضطربت أحوالُ الولايات الشرقية عمومًا، وسعت كلُّ أمة من الأمم المختلفة النازلة بها للحصول على الاستقلال، وكان من أهَمِّ الحركات حركةُ الأكراد بقيادة رجل كردي يلقَّب بجان بولاد، والأمير فخر الدين المعني الثاني الدرزي، وغيرهما، لكنْ قيَّض الله للدولة في هذه الشدة الوزير مراد باشا الملقب بقويوجي الذي عُيِّن صدرًا أعظم، وكان قد تجاوز الثمانين؛ ليكون عونًا وعضدًا للسلطان الفتى، فتقلد مع كِبَرِ سِنِّه ووَهَنِ قواه قيادةَ الجيوش وحارب الثائرين بهمَّة ونشاط زائِدَينِ، فانتصر على فخر الدين الدرزي, وجان بولاد الكردي، واستمال قلندر أوغلي أحد زعماء الثورة في الأناضول، وقبض على آخر يدعى أحمد بك وقتله بعد أن فرَّق جنده بالقرب من قونية، وفي سنة 1608 م انتصر على من بقِيَ من العصاة بقرب وان، وفي السنة التالية قَتَل آخر زعماء الثورة المدعو يوسف باشا الذي كان استقَلَّ بصاروخان ومنتشا وآيدين, وبذلك عادت السكينة وساد الأمن بهمَّة هذا الشجاع الذي لُقِّب بسيف الدولة عن استحقاق, وازدادت في أيام السلطان أحمد العلاقاتُ السياسية مع دول الإفرنج، فجددت مع فرنسا العقود والعهود القديمة مع بعض زيادات طفيفة، وفي سنة 1609 جُدِّدت مع مملكة بولونيا- بولندا- الاتفاقات التي أُبرِمَت معها في زمن السلطان محمد الثالث، وأهمُّ ما بها تعهُّد بولونيا بمنع قوزاق الروسية من الإغارة على إقليم البغدان، وتعهُّد الدولة العلية بمنع تتار القرم من التعدي على حدودها، وفي سنة 1612م تحصلت ولايات الفلمنك على امتيازات تجارية تضارع ما مُنحِتَه كلٌّ من فرنسا وإنكلترا, والفلمنك هم الذين أدخلوا في البلاد الإسلامية استعمالَ التبغ (الدخان) فعارض المفتي في استعمالِه وأصدر فتوى بمنعِه، فهاج الجند واشترك معهم بعضُ مُستخدَمي السراي السلطانية، حتى اضطروه إلى إباحته! وفي الثالث والعشرين من ذي القعدة من هذه السنة توفي السلطان أحمد ودُفِن عند جامع سلطان أحمد، وكانت مدة حكمه أربعة عشر عامًا, ولصِغَرِ سِنِّ ابنه عثمان الذي لم يتجاوَزْ ثلاث عشرة سنةً من عمره خالف السلطانُ أحمد العادة المتَّبَعة من ابتداء الغازي عثمان الأول بتنصيب أكبر الأولاد أو أحدهم مكان والده، فأوصى بالمُلكِ من بعده لأخيه مصطفى الأول."},{"id":3865,"title":"خلع السلطان العثماني مصطفى الأول وتولية ابن أخيه عثمان .","date":["العام الهجري :1027","الشهر القمري : صفر","العام الميلادي :1618"],"text":"لم تدُمْ أيام السلطان مصطفى الأول بن مراد الثالث كثيرًا؛ فقد خُلِع من السلطة بعد ثلاثة أشهر وثمانية أيام فقط؛ بدعوى أنَّه لا يعرف بأمورِ الحكم شيئًا، بحُكمِ أنَّه كان طول حياة أخيه أحمد محجوزًا عليه عند الجواري والخَدَم، وقيل: كان ذلك بتدبير فرنسا، ثمَّ تم تولية ابن أخيه عثمان بن أحمد الأول الذي كان ما يزال في الثالثة عشرة من عمره، فكان أول ما عمله أن أطلق سراحَ القنصل الفرنسي ومترجِمه، اللذين كان قد حبسهما عمه مصطفى الأول؛ لتدخُّلِهم في شؤون الدولة العثمانية، ولمساعدة أحد البولونيين على الهرب من السجن، واعتذر عثمانُ من ملك فرنسا عن هذا الحدث!"},{"id":3866,"title":"انتصار الصفويين على العثمانيين في معركة بول شكسته .","date":["العام الهجري :1027","الشهر القمري : رمضان","العام الميلادي :1618"],"text":"انتصر الصفويون على العثمانيين في معركة \"بول شكسته\"، وخسر العثمانيون في هذه المعركة 15 ألف قتيل."},{"id":3867,"title":"توقيع الدولة العثمانية معاهدة \"أردبيل\" مع إيران .","date":["العام الهجري :1028","الشهر القمري : محرم","العام الميلادي :1619"],"text":"وقَّعت الدولة العثمانية معاهدةَ أردبيل مع إيران، وقد خفضت هذه المعاهدة كمية الحرير التي كانت تقَدِّمُها إيران سنويًّا، كخراج للدولة العثمانية إلى نصف ما قررته معاهدة إستانبول الموقَّعة بين الدولتين!"},{"id":3868,"title":"ثورة محمد بن الشيخ المأمون السعدي المعروف بزغودة على أخيه .","date":["العام الهجري :1028","الشهر القمري : شعبان","العام الميلادي :1619"],"text":"لما رأى أهل بلاد الهبط ما وقع من افتراق الكلمة وتوقُّد الفتن، بايعوا محمد بن الشيخ المعروف بزغودة، وكان الذي قام بدعوته الشريفَ أبا الحسن علي بن محمد بن علي بن عيسى بن عبد الرحمن الإدريسي المحمدي اليونسي المعروف بابن ريسون، وهي أم جدة علي نزيل تاصروت، وبايعوه على الكتاب والسنة، وعلى إحياء الحق وإماتة الباطل، فلما بلغ خبَرُه أخاه عبد الله، خرج لقتاله فالتقى الجمعان بوادي الطين واقتتلوا، فانهزم عبد الله وتقدم محمد إلى فاس فدخلها واستولى عليها في شعبان من هذه السنة، وقبض على بعض عمَّال عبد الله فقتلهم واستصفى أموالهم، وفي آخر شعبان وقعت الحربُ بينهما بمكناسة فانهزم محمد ودخل عبد الله فاس في مستهل رمضان من السنة وأظهر العفوَ عن الخاصِّ والعامِّ، ثم قتل أهلُ فاس قائدَه ابنَ شعيب وأخذوا حِذرَهم من عبد الله، ثم وقع قتال بين أهل الطالعة وأهل فاس الجديد ودام أيامًا عديدة حتى اصطلحوا لتاسع رجب من سنة 1029 ثم إن عبد الله خرج لقتال أخيه محمد، فوقعت المعركة بينهما بوادي بهت، فانهزم محمد وفرَّ شريدًا إلى أن قتله ابنُ عمه"},{"id":3869,"title":"انتصار الجيش العثماني على جيش بولونيا .","date":["العام الهجري :1029","الشهر القمري : ذي القعدة","العام الميلادي :1620"],"text":"انتصر الجيشُ العثماني أيام عثمان الثاني الذي أعلن الجهادَ ضِدَّ بولونيا-بولندا- فأرسل جيشًا من الانكشارية بقيادة الوزير غازي إسكندر باشا، وتمكَّن العثمانيون من إبادة الجيش البولوني الذي كان يبلغ قوامُه ستين ألف جندي، ولم ينجُ من المعركة إلا أربعُمائة جندي بولوني فقط! وكان سبب المعركة هو تدخُّل بولونيا في شؤون إمارة البغدان من المجر. لكنْ حدَثَ الصُّلحُ بعد ذلك بناءً على رغبة بولونيا، وطلب الانكشارية الذين تَعِبوا من مواصلة القتال."},{"id":3870,"title":"الدولة العثمانية تعقد معاهدة \"خوتين\" مع بولونيا .","date":["العام الهجري :1030","الشهر القمري : ذي القعدة","العام الميلادي :1621"],"text":"وقَّعت الدولة العثمانية معاهدة \"خوتين\" مع بولونيا، واتَّفق الطرفان على الصلح بعد اشتعال الحرب بينهما، واتَّفقا على أن تقوم بولونيا بهدم جميعِ القلاع التي شيَّدتْها على حدود الدولة العثمانية، وأن تدفعَ ضريبةً سنويةً إلى القرم التي كانت تخضَعُ للدولة العثمانية, وأن تترك بولونيا قلعة \"خوتين\" الهامة للدولة العثمانية."},{"id":3871,"title":"وفاة الإمام العلامة زين الدين المناوي الشافعي .","date":["العام الهجري :1031","الشهر القمري : صفر","العام الميلادي :1622"],"text":"هو الإمامُ العلَّامة زين الدين محمد عبد الرؤوف بن تاج العارفين بن علي بن زين العابدين الحدادي المناوي القاهري، ولد سنة 952 بمنى، وهي قرية من قرى مصر. كان أعلَمَ معاصريه بالحديث وأكثَرَهم فيه تصنيفًا وإجادةً وتحريرًا، أخذ التفسير والحديث عن النور علي بن غانم المقدسي، والنجم الغيطي، والشمس الرملي، وأخذ التصوُّفَ عن جماعة، منهم الشيخ منصور الغيطي، والشعراني، وغيرهما. قال عبد الحي الكتاني: \"لم يخلُ من طاعنٍ وحاسدٍ حتى دسَّ عليه السمُّ؛ لكون أهل عصره كانوا لا يعرفون مرتبةَ عِلمِه ؛لانزوائه عنهم وانقطاعِه للتصنيف\". برعَ في الحديث وله مصنَّفات عديدة، منها: فيض القدير في شرح الجامع الصغير, والفتح السماوي بتخريج أحاديث تفسير القاضي البيضاوي, والجامع الأزهر في حديث النبي الأنور, والإتحافات السَّنية بالأحاديث القدسية, والتوقيف على مهمات التعاريف, والكواكب الدُّرية في تراجم الصوفية, وغيرها من الكتب."},{"id":3872,"title":"خلع السلطان عثمان الثاني وقتله وإعادة عمه مصطفى الأول .","date":["العام الهجري :1031","الشهر القمري : رجب","العام الميلادي :1622"],"text":"هو الخليفةُ عثمان الثاني بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد الأول جلبي بن بايزيد الأول بن مراد الأول بن أورخان غازي بن عثمان بن أرطغرل. وُلِد بإستانبول سنة 1013 ولَمَّا توفي والده أحمد الأول سنة 1026لم يرشِّحْه للخلافة لصِغرِ سِنِّه، ورشح أخاه مصطفى الأول، لكنه لم يلبث على سرير الملك إلا ثلاثة أشهر؛ حيث عزلَه في أول سنة 1027 أربابُ الغايات، وفي مقدمتهم المفتي وآغا السراي، وساعدهم الانكشارية على ذلك لتوزيع الهبات عليهم عند تولية كل ملكٍ جديدٍ، وأقاموا مكانه السلطان عثمان الثاني, وفي بداية حكمه أمر بإطلاق قنصل فرنسا وأرسل مندوبًا لملك فرنسا يعتذر عما حصل من الإهانة لسفيره, وعندما تدخَّلت بولونيا في شؤون إمارة البغدان لمساعدة جراسياني الذي عُزل بناءً على مساعي أمير ترنسلفانيا، اتخذ السلطان عثمان هذا التدخُّلَ سببًا في إشهار الحرب على مملكة بولونيا وتحقيق أمنيتِه، وهي فتح هذه المملكة وجعْلها فاصلًا بين أملاك الدولة ومملكة روسيا التي ابتدأت في الظهور، وقبل الشروع في الحرب أصدر أمرًا بتقليل اختصاصات المفتي ونزْع ما كان له من السلطةِ في تعيين وعزل الموظفين، وجعل وظيفتَه قاصرة على الإفتاء، حتى يأمن شَرَّ دسائسه التي ربما تكون سببًا في عزله، كما كانت سبب عَزلِ سلَفِه، لكن أتى الأمرُ على الضدِّ بما كان يؤمِّل, وبعد أن أتمَّ هذه التمهيدات الداخلية سيَّرَ الجيوش والكتائب لمحاربة مملكة بولونيا، فلما طالت الحربُ طلبت الانكشارية منه الكَفَّ عن الحرب, فحَنِق السلطان على الانكشارية من طلَبِهم الراحة وخلودهم إلى الكسل وإلزامه على الصلح مع بولونيا، فعزم على التخلُّص من هذه الفئة الباغية، ولأجل الاستعداد لتنفيذ هذا الأمر الخطير أمر بحشدِ جيوش جديدة في ولايات آسيا، واهتمَّ بتدريبها وتنظيمها، وشرع فعلًا في تنفيذ هدفه، وعلمت الانكشارية بذلك فهاجوا وماجوا وتذمَّروا واتفقوا على عزل السلطان، وتم لهم ذلك في 9 رجب من هذه السنة ثم قتلوه. بعد أن حكم أربع سنوات وأربعة أشهر, وأعادوا مكانه السلطان مصطفى الأول المخلوع سابقًا!"},{"id":3873,"title":"خلع السلطان العثماني مصطفى الأول للمرة الثانية وتولية ابن أخيه .","date":["العام الهجري :1032","الشهر القمري : ذي القعدة","العام الميلادي :1623"],"text":"تولى السلطانُ مصطفى الحكمَ للمرة الثانية إثرَ فتنة الانكشارية، وصارت الحكومةُ ألعوبةً بأيديهم، ينصبون الوزراء ويعزلونهم بحسَبِ أهوائهم، وأصبحت المناصب تُباعُ جِهارًا، وارتكبوا أنواعَ المظالم، وتغير الوزراء الصدورُ في مدَّتِه هذه سبعَ مرَّات خلال عام واحد وأربعة شهور، وكان الخلافُ قد دبَّ بين أمراء الأناضول وفرقة السباهية- الخيالة- على استمرار الوزراء الصدور، حتى إن بعضهم لم يُكمِل شهرًا واحدًا، ونظرًا لضعف السلطانِ وعجزه عن إدارة شؤون البلاد، واستمرارًا لهذا العبثِ، قام الانكشارية بعزل السلطان مصطفى الأول وولَّوا مكانه ابن أخيه السلطان مراد الرابع، ولصغر سنه صارت والدته كوسم نائبةَ السلطنة، تقوم بالأمر دونَه، لكن مقاليد الأمور كانت بيد الانكشارية التي علا شأنُها وازداد نفوذُها!"},{"id":3874,"title":"ثورة أباظة باشا على الدولة العثمانية .","date":["العام الهجري :1033","العام الميلادي :1623"],"text":"أعلن والي أرضروم أباظة باشا العصيانَ مدَّعيًا أنه يريد الانتقام للمرحوم السلطان عثمان شهيد الانكشارية، فدخل سيواس وأنقرة، فسار إليه الصدرُ الأعظم حافظ باشا، وبعد معركة قيصرية قضى على هذه الثورة، ثم سار القائدُ حافظ باشا إلى بغداد غير أنَّ الانكشارية لم يستمروا معه في القتال، فعزل بسبب ذلك القائد حافظ باشا، فعاد أباظة باشا للثورة وأحرز نصرًا على الدولة العثمانية، فسار إليه خسرو باشا الصدر الأعظم الجديد، وأدخله في الطاعة وعيَّنه واليًا على البوسنة عام 1037هـ."},{"id":3875,"title":"وفاة الفقيه مرعي الكرمي الحنبلي .","date":["العام الهجري :1033","الشهر القمري : ربيع الأول","العام الميلادي :1624"],"text":"هو الفقيه زين الدين مرعي بن يوسف بن أبي بكر بن أحمد الكرمي المقدسي الحنبلي، وهو كذلك مؤرِّخ وأديب، من أهل طولكرم قرب نابلس، درَّس في القدس والقاهرة، وعمل مدرسًا في الجامع الأزهر والمسجد الطولوني، كان من كبارِ فُقهاء الحنابلة، له سبعون مصنَّفًا، منها: أقاويل الثقات في تأويل الأسماء والصفات، والآيات والفوائد الموضوعة في الأحاديث الموضوعة، وتحقيق الخلاف في أصحاب الأعراف، وتوضيح البرهان في الفرق بين الإسلام والإيمان، وغيرها من المصنفات."},{"id":3876,"title":"الصفويون يحتلون بغداد .","date":["العام الهجري :1034","العام الميلادي :1624"],"text":"قام قائدُ الشرطة في بغداد بكير آغا بقتلِ الوالي وتسلَّم الأمرَ مكانه، فأرسلت له الدولةُ العثمانية قوةً بقيادة حافظ باشا، فحاصره في بغداد، فقام بالاتصال بالشاه عباس الصفوي، وعرض عليه تسليمَ المدينة فسار إليه, وفي الوقت نفسِه اتصل آغا بالقائد العثماني المحاصِر له وعرض عليه تسليمَ المدينة على أن يتسلَّم هو ولايتَها، فوافق القائد ودخلت جنودُه المدينة قبل وصول الشاه، ولَمَّا وصل الشاه وألقى الحصارَ عليها مدة ثلاثة أشهر اتصل بابن بكير آغا وأغراه بتسليم الولاية، فوافق وخان الدولة، ودخل الشاه بغداد وقتل بكير آغا وابنَه."},{"id":3877,"title":"وفاة السلطان جهانكير بن أكبر شاه الكوركاني .","date":["العام الهجري :1036","الشهر القمري : صفر","العام الميلادي :1626"],"text":"هو السلطان نور الدين محمد جهانكير بن أكبر بن همايون بن بابر الكوركاني المغولي، من سلالة تيمورلنك سلطان الهند، ولِدَ في ربيع الأول سنة 977 بأكبر آباد، وتولى المملكة بعد والده يوم الخميس لأربع عشرة خلت من جمادى الآخرة سنة 1014، وكان اسمُه سليمًا، سماه به والده على اسم الشيخ سليم بن بهاء الدين السيكروي؛ لأن الشيخ بشَّر به والده قبل ولادته ودعا له، فلما استقلَّ بالملك لقَّب نفسَه نور الدين محمد جهانكير، وافتتح أمرَه بالعدل والسخاء، وقرَّب إليه العلماء، وكان صحيح العقيدة خلافًا لوالده، سمع الحديث من الشيخ محمد سعيد الهروي المشهور بمير كلان، وقرأ عليه شيئًا من العلم بأمر والده، وسمع أيضًا من المفتي صدر جهان البهانوي. تزوج بمهر النساء بنت غياث الدين الطهراني، وكانت عشيقته، فخطبها بعد ما قَتَل بعلها شيرافكن خان، فأبت ثم رضيت، فتزوج بها ولقَّبها نور جهان بيكم، فحُبِّبت إليه وملكت فؤادَه حتى ألقى زمام السلطنة بيدها، فدبَّرت لخَتنها شهريار بن جهانكير من زوجته الأخرى ليولِّيه الملك، ورغَّبت زوجها جهانكير عن ابنه شاهجهان الذي دبَّر الملك لولايته بالمُلك بعده، فوقع الخلافُ بينهما وآل إلى الحرب، وتوفي جهانكير ساخطًا عنه. وكان جهانكير رحيمًا حليمًا كريمًا شاعرًا لطيف الطبع، حسن المعاشرة ظريف المحاضرة، حسن الصورة سليم الذهن، باهر الذكاء فصيح العبارة، له يد بيضاء في التحرير والتحبير، صنَّف كتابًا في أخباره وسماه \"تزك جهانكيري\" وهو مقبول متداول في أيدي الناس، وصنف في أخباره معتمد خان كتابَه: إقبال نامه، ومرزا كامكار الملقب بعزت خان كتابه مآثر جهانكيري، ومن مصنفات جهانكير بندنامه بالفارسية في أوراق عديدة صنفه لأبنائه، وأمر الشيخ محمد ابن الجلال الحسيني الكجراتي أن يترجم القرآن الكريم بالفارسية ولا يباشر فيه التصنع، ولا يزيد على الترجمة اللفظية حرفًا من جانبه. توفي لثلاث بقين من صفر سنة ست وثلاثين وألف، وكانت مدت حكمه إحدى وعشرين سنة وثمانية أشهر وثلاثة عشر يومًا."},{"id":3878,"title":"وفاة الشاه عباس الأول الصفوي وتولي صفي بن صفي .","date":["العام الهجري :1037","العام الميلادي :1627"],"text":"هو الشاه الصفوي عباس الكبير الأول بن محمد خدابنده بن طهماسب بن إسماعيل الأول. ولد عباس في مدينة حيرات الواقعة في أفغانستان في 27/1/1571م. تولى حكم الدولة الصفوية سنة 996 بعد أن تمرد على والده ثم نحاه عن الحكم؛ لأنه لم يستطع ضبط الاضطرابات التي عمت البلاد بسبب ضعف شخصيته, ويعتبر عباس هو رابع حكام الدولة الصفوية ومن أقوى وأشرس حكامها, وقد أعاد لها قوتها كما كانت عليه في عهد إسماعيل الأول, فتمكن من سحق الأكراد والأوزبكية السنَّة الذين يعتبرهم أعداءً للدولة، كما حقق انتصارات على العثمانيين، ودخل في تحالفات مع الدول الأوربية ضد الدولة العثمانية، واهتم بتنظيم الدولة إداريًّا وحضاريًّا، وقد كان سفاكًا للدماء متناقضًا في شخصيته بين التدين والفجور، والعدل والظلم! توفي بعد أن دام في الملك قرابة إحدى وأربعين سنة، ثم تولى بعده صفي بن صفي ميرزا بن عباس."},{"id":3879,"title":"وفاة السلطان زيدان بن أحمد السعدي وقيام ابنه عبد الملك .","date":["العام الهجري :1039","العام الميلادي :1629"],"text":"هو السلطان أبو المعالي زيدان بن أحمد المنصور الذهبي السعدي، زعيم الأشراف في المغرب الأقصى. كان في أيام أبيه مقيمًا بتادلا أميرًا عليها، تولى بعد وفاة والده المنصور سنة 1012حيث اجتمع أهل الحَل والعقد من أعيان فاس وكبرائها والجمهور من جيش المنصور على بيعة ولده زيدان، وقالوا إن المنصور استخلفه في حياته ومات في حجره، وكان المنصور قد عزل ابنه الكبير الشيخ المأمون وسجنه في مراكش لفساده وتمرده، فلما تمت البيعة لزيدان انتفض عليه أخواه أبو فارس ومحمد الشيخ المأمون، فحارباه وهزما جيشه. فلحق زيدان بتلمسان. وجعل يتنقل بين سجلماسة ودرعة والسوس ومعه فلول من جيشه، يدعو الناس إلى مناصرته على أخويه، حتى استجاب له أهل مراكش، فنادوا به سلطانًا سنة 1015, ولكن لم يلبث أن أخرجه منها أخوه المأمون سنة 1016 فلجأ إلى الجبال مدة يسيرة، وعاد فامتلك مراكش في السنة نفسها. وقويت شوكته، فاستولى على فاس سنة 1017 وأخرجه منها أنصار المأمون سنة 1018 واستمر السلطان زيدان مالكًا مراكش وأطرافها إلى أن توفي بعد أن أمضى قرابة السبع وعشرين سنة في الملك، وخلفه بعده ابنه أبو مروان عبد الملك الذي تقاتل مع أخويه الأميرين الوليد وأحمد وهزمهما."},{"id":3880,"title":"استيلاء الجيش العثماني على مدينة همدان .","date":["العام الهجري :1039","الشهر القمري : ذي القعدة","العام الميلادي :1630"],"text":"استولى الجيش العثماني بقيادة خسرو باشا على مدينة همدان، الواقعة على بعد 250 كم جنوب غرب طهران."},{"id":3881,"title":"بناء قصر تاج محل ليكون أشهر الرموز الإسلامية بالهند .","date":["العام الهجري :1041","العام الميلادي :1631"],"text":"تاج محل بالهند هو مَعلَم معماري هندي يقع في آكرا، يعتبر من أكبر الشواهد على الفنون والعمارة في العهد المغولي. شُيِّد الضريح تخليدًا لذكرى أرجونمد بانو باكام، والتي اشتهرت بلقب ممتاز محل، وكانت هي الزوجة المحظية لدى السلطان شاه جهانكير, والتي توفيت سنة 1631م أثناء إحدى الحملات العسكرية ويقع ضريحها بالقرب من ضريح زوجها الذي توفي سنة 1666م، وتطلَّب تشييد هذا المعلم عشرين عامًا وتجنيد أكثر من عشرين ألف رجل، ويبلغ ارتفاع الضريح المبنى الرئيسي 73 مترًا، نقشت عليه آيات قرآنية، وبعض الرسومات البارزة والتي تعتبر مرجِعًا لدراسة فن الرسم في الهند أثناء العهد المغولي. ينتصب الضريح على منصة مربعة، وعلى كل جانب منها منارة دائرية. إلى يمينه شيِّد مسجد صغير، وإلى اليسار ينتصب مبنى يقال له جواب، أوجد لإحداث توازن (مع المسجد) في الشكل العام للضريح، ولا تقام فيه الصلوات لأنه ليس باتجاه القبلة، بينما تقام في المسجد الآخر الذي يقع في جهة اليسار. يتم الولوج إلى الضريح بعد العبور على الحدائق الواقعة داخل مساحة مطوقة تتخللها بوابة كبيرة. جمعت المساجد والأضرحة الأخرى- للزوجات الأقل حظًّا- بالقرب من المكان. يُوجد النُّصُبان التذكاريان لكل من ممتاز محل وشاه جهان في قاعة ثُمانية الأضلاع، أُنجزت النقوش التي توجد عليهما بطريقة متقنة، وتمت إحاطتهما بستائر مخرومة ومطعمة بالمرمر والأحجار الكريمة. لا يعرف بالضبط صاحب هذا العمل، إلا أنه يرجح أن يكون المهندس المعماري أستاذ عيسى (هو من أصول تركية أو فارسية) إلى جانب خان رومي الذي أشرف على أعمال بناء القبة، ورانمال الذي قام بتخطيط الحدائق."},{"id":3882,"title":"السلطان العثماني مراد الرابع يقضي على ثورة الانكشارية .","date":["العام الهجري :1041","العام الميلادي :1631"],"text":"سيطر الجيشُ الانكشاري على السلطان مراد الرابع في أول أمره لصغره، ثم إنَّه لم يلبث أن عرف أمور الحكم حتى بدأ بالقضاء على طغاة العسكر الذين قتلوا أخاه السلطان عثمان الثاني، وأَعدم جميع المتأسِّدين في إستانبول وفي جميع أنحاء الدولة، وأسَّس تشيكلات قوية للمخابرات وثبَّت من خلالها أسماء جميع المستبدين في الدولة، وكان إذا صادف بلدًا في أسفاره يدعو مستبديها بأسمائهم ويعدمهم، ومنع في عهده الخمر والتدخين وأعدم كلَّ مرتدٍّ عن الإسلام."},{"id":3883,"title":"نشوب حريق هائل في إستانبول .","date":["العام الهجري :1043","الشهر القمري : صفر","العام الميلادي :1633"],"text":"نشب حريق هائل في إستانبول أدى إلى احتراق 20 ألف منزل، وقد نجم الحريق عن تدخين التبغ (السجائر)؛ مما دفع الدولة العثمانية إلى إصدار قرار بمنع التدخين حتى في المنزل، وقد رُفع الحظر عن التدخين عام 1640م."},{"id":3884,"title":"مقتل شيخ الإسلام زادة حسين أفندي .","date":["العام الهجري :1043","الشهر القمري : رجب","العام الميلادي :1634"],"text":"هو شيخ الإسلام أخي زادة حسين أفندي تولى منصب المشيخة الإسلامية على أيام السلطان مراد الرابع، ولد في إستانبول عام 980هـ، وبعد أن حصَّل العلم تولى قضاء إستانبول في عام 1014هـ، ثم أصبح قاضي عسكر الأناضول عام 1020هـ، ثم قاضي عسكر الروملي في سنة 1032ه، ثم تولى المشيخة الإسلامية في سنة 1041ه، وكان عالمًا له بعض تعليقات على كتب التدريس، ونظَم الشعر بمخلص هدايي، وأقام مدرسة في مواجهة داره، كما قام بتحويل كنيسة في بلاط إلى جامع. ثم لم يلبث بعد عامين من تعيينه منصب المشيخة الإسلامية أن تم عزله وقتله نتيجة لسعاية البعض؛ وكان ذلك أول قتل لأحد العلماء في الدولة العثمانية، وقد هدف السلطان إلى تأكيد هيبة الدولة التي كانت تواجه عددًا من الأزمات الداخلية، خاصة من بعض طوائف الجيش."},{"id":3885,"title":"وفاة عبد الملك الثاني سلطان السعديين وقيام أخيه الوليد .","date":["العام الهجري :1044","العام الميلادي :1634"],"text":"هو السلطان أبو مروان عبد الملك الثاني بن زيدان بن أحمد المنصور الذهبي سلطان السعديين بالمغرب الأقصى، تولى الحكم بعد وفاة والده السلطان زيدان, ولما تمت له البيعة ثار عليه أخواه الوليد وأحمد، فوقعت بينه وبينهما معارك وحروب إلى أن هزمهما واستولى على ما كان بيدهما من العُدة والذخيرة وفَرَّ أحمد إلى بلاد الغرب، فدخل عبد الملك فاس يوم الجمعة الخامس والعشرين من صفر بعد وفاة أبيه بستة وأربعين يومًا، فاتَّسم بسمة السلطان وضرب سكته وفي ثالث عشر شوال من السنة عدا على ابن عمه محمد بن الشيخ المعروف بزغودة فقتله غدرًا بالقصبة، وفي سنة 1037 سجن أخاه أحمد بفاس الجديد. قُتل أبو مروان على يد بعض أهل مراكش بإيعاز من أخيه الوليد، وتولى أخوه الوليد خلفًا له."},{"id":3886,"title":"منع الدولة العثمانية تناول المشروبات الكحولية .","date":["العام الهجري :1044","الشهر القمري : صفر","العام الميلادي :1634"],"text":"أصدر السلطان العثماني مراد الرابع أمرًا بمنع تناول المشروبات الكحولية في أرجاء الدولة العثمانية، وحظَر تناولها على المسلمين حتى في بيوتهم، وأُغلقت الحانات، وهَدَّدت الدولة العثمانية بإعدامِ كلِّ من يشرب الخمر في محلِّ ارتكاب الجريمة."},{"id":3887,"title":"معارك بين العثمانيين والزيدية في اليمن .","date":["العام الهجري :1045","العام الميلادي :1635"],"text":"بدأت المعارك بين العثمانيين والإمام المنصور القاسم بن محمد باليمن عام 1022هـ وانتصرت قوات الإمام وانسحب العثمانيون إلى صنعاء، ثم اضطر القائد جعفر باشا لعقد الصلح مع الإمام، واستمر عامًا واحدًا، ثم تجدد القتال حتى استطاع الإمام السيطرة على شمال اليمن عام 1029هـ ثم توفي من العام نفسه، وتولى ابنه المؤيد الذي استطاع أن يصل إلى أبواب صنعاء حيث جرت في هذا العام بينه وبين العثمانيين معركة اضطرت القائد العثماني لفتح أبواب المدينة، وبدأ العثمانيون بالانسحاب والتراجع، وكان هذا هو الانسحابَ الثاني لهم، ودخل المؤيد زبيد وجزر قمران وجزر فرسان."},{"id":3888,"title":"استقلال اليمن عن الخلافة العثمانية بعد جلاء قواتها عنها .","date":["العام الهجري :1045","العام الميلادي :1635"],"text":"بعد وفاة المطهر بن شرف الدين زعيم الجبهة الزيدية وقائد المقاومة عام 980هـ, انتهى دور آل شرف الدين لتعقبهم فترة تدهور للمقاومة ضد الأتراك، واستمر الوضع ربع قرن حتى ظهر الإمام القاسم بن محمد، قائدًا لثورة عارمة ضد العثمانيين، وأسس جيلًا جديدًا من الأئمة الزيدية واستمروا في حكم اليمن بين مد وجزر حتى زمن الثورة الجمهورية عام 1962م، وقد تميَّز تاريخ الفترة اللاحقة بالنضال الدؤوب من قبل اليمنيين جميعًا بزعامة الأئمة من بيت الإمام القاسم بن محمد الذي تمكن من فرض صلح مع الوالي العثماني محمد باشا يحق للإمام بمقتضاه من حكم المناطق الشمالية لصنعاء على المذهب الزيدي المخالف لمذهب العثمانيين السُّني الحنفي، وبعد وفاة الإمام القاسم عام 1029هـ / 1620م, خلفه ابنه محمد الملقب بالمؤيد، وهو الذي تمكن بعد انتقاض الصلح بين الطرفين من مقارعة الأتراك، وتم طردهم نهائيًّا من اليمن عام 1045هـ / 1635م, وصارت بذلك اليمن أول ولاية عربية تخرجُ عن فلك الدولة العثمانية، ولكنَّها عادت إلى اليمن ثانية عام 1266هـ / 1848م أي بعد أكثر من قرنين من الزمان."},{"id":3889,"title":"العثمانيون يخمدون ثورة الأمير فخر الدين الثاني الدرزي في لبنان .","date":["العام الهجري :1045","العام الميلادي :1635"],"text":"كان السلطان عثمان الثاني قد عفا عن فخر الدين المعني الثاني وسمح له بالعودة إلى جبل لبنان، فبدأ من جديد بالتحرُّك للثورة والعصيان على الدولة العثمانية، فثار مرة أخرى في لبنان فنهض إليه والي دمشق وانتصر عليه وأسره وولديه وأرسلهم إلى إستانبول غير أن الخليفة مراد الرابع عاملهم بغاية الكرم رغم أنهم أكثر الناس خيانة باتصالهم الدائم بالصليبيين والطليان خاصة، وهذا ما شجَّع قرقماز حفيد فخر الدين بالتحرك والثورة فأعاد الخليفة النظر, فقتل فخر الدين وابنه الكبير وأرسل إلى قرقماز من أخضعه."},{"id":3890,"title":"العثمانيون يفتحون مدينة تبريز .","date":["العام الهجري :1045","العام الميلادي :1635"],"text":"سار الخليفة مراد الرابع بنفسه إلى الصفويين وفتح بعض القلاع ثم انطلق إلى مدينة تبريز فدخلها عَنوة في هذا العام."},{"id":3891,"title":"وفاة السلطان الوليد بن زيدان ملك السعديين وتولي أخيه محمد .","date":["العام الهجري :1045","العام الميلادي :1635"],"text":"هو السلطان الوليد بن زيدان بن أحمد المنصور الذهبي ملك السعديين في المغرب الأقصى لما قُتل أخوه السلطان عبد الملك بن زيدان سنة 1044 بويع أخوه الوليد بن زيدان فلم يزل مقتصرًا على ما كان لأخيه وأبيه من قبله لم يجاوز سلطانه مراكش وأعمالها، وعظمت الفتن بفاس حتى عُطِّلت الجمعة والتراويح من جامع القرويين مدة ولم يصَلِّ به ليلةَ القدر إلا رجل واحد من شدة الهول والحروب التي كانت بين أهل المدينة؛ فقد اقتسم المغرب أيام أولاد زيدان طوائف، فكان حاله كحال الأندلس أيام ملوك الطوائف. كان الوليد بن زيدان متظاهرًا بالديانة لين الجانب حتى رضيته الخاصة والعامة، وكان مولَعًا بالسماع لا ينفكُّ عنه ليلًا ولا نهارًا إلا أنه كان يقتل الأشراف من إخوته وبني عمه حتى أفنى أكثرهم، وكان مع ذلك محبًّا للعلماء مائلًا إليهم بكليته متواضعًا لهم, وأما وفاته فسببها أن جنده من العلوج طالبوه بمرتبهم وأُعْطياتهم على العادة وقالوا له أعطنا ما نأكل، فقال لهم على طريق التهكم: كلوا قشر النارنج بالمسرة، فغضبوا لذلك وكمن له أربعة منهم فقتلوه غدرًا يوم الخميس الرابع عشر من رمضان من هذه السنة. قيل: \"لما ولي الوليد قتل أخاه إسماعيل واثنين من أولاد أخيه عبد الملك، وسبعة من بني عمه، ولم يترك إلا أخاه الشيخ بن زيدان استصغارًا له إذ كان سنه يومئذ إحدى عشرة سنة، وكانت أمه تخاف عليه من الوليد، فكانت تحرسه منه حراسة شديدة، وأمرت نساء القصر بحراسته من أخيه الوليد\" ثم إن رؤساء الدولة سئموا ملكته فاتفقوا مع نساء القصر على قتلِه وكان الوليد عازمًا على قتل أخيه الشيخ، فكان من قدر الله أنَّ العلوج قد عزموا على قتله، فكمنوا له في حجرة كان محبوسًا فيها الشيخ، فلما دخل الوليد إلى الحجرة التي فيها الشيخ فوجئ بالأعلاج كامنين له هناك، فلما رآهم فزع وقال ما لكم فرموه بالرصاص، ثم تناولوه بالخناجر حتى فاضت روحه. لما توفي الوليد قام أخوه محمد خلفًا له."},{"id":3892,"title":"استيلاء السلطان العثماني مراد الرابع على مدينة \"روان\" الإيرانية .","date":["العام الهجري :1045","الشهر القمري : صفر","العام الميلادي :1635"],"text":"عمل السلطان مراد الرابع على إعادة قوة الدولة العثمانية وعودة عمليات الفتح والتوسع كما كانت عليه في عهد سليمان القانوني، فقاد السلطان العثماني مراد الرابع حملة عسكرية بنفسه لغزو إيران حتى تمكن من الاستيلاء على مدينة \"روان\" الإيرانية، التي استسلمت بعد 11 يومًا من الحصار. وكان العثمانيون يسيطرون على المدينة منذ سنة 1583م حتى 1604م، ثم فقدوا السيطرة عليها 31 عامًا كانت فيها خاضعة لحكم الصفويين."},{"id":3893,"title":"قيام حرب بين أهل الأندلس واللمطيين .","date":["العام الهجري :1045","الشهر القمري : جمادى الأولى","العام الميلادي :1635"],"text":"قامت حرب بين أهل الأندلس واللمطيين، وانتُهبت فيها السلع التي بسوق القيسارية- السوق الكبير- وسوق العطارين، وبنى اللمطيون الدرب الذي بباب العطارين، واستمرت الحرب نحو ثمانية أيام ثم اصطلحوا، وكان سببها مقتل أحمد ولد ابن الأشهب على يد علي بن سعد في جامع القرويين وهو في صلاة العصر، وذلك في رابع جمادى الأولى من هذه السنة."},{"id":3894,"title":"انتصار الإيرانيين على العثمانيين في معركة مهران .","date":["العام الهجري :1046","الشهر القمري : ربيع الآخر","العام الميلادي :1636"],"text":"انتصر الإيرانيون على العثمانيين في معركة مهران، وقد قُتل في هذه المعركة الوزير العثماني كوجوك أحمد باشا، وقد أعاد الإيرانيون جسده إلى العثمانيين نظرًا لشجاعته في القتال."},{"id":3895,"title":"حرب العثمانيين مع الصفويين ودخول العثمانيين بغداد .","date":["العام الهجري :1048","العام الميلادي :1638"],"text":"اندلعت الحرب مع الشيعة الصفوية في العراق عام 1044هـ/1634م، فقاد السلطان مراد الرابع الجيوش بنفسه واتجه إلى بغداد، وكان عباس شاه فارس قد استولى عليها وقتل واليها العثماني وأذل أهل السنَّة بها وعمل بهم الأفاعيل، فحاصر السلطان مراد بغداد وهدم جزءًا كبيرًا من أسوارها بالمدفعية ودخلها, وقتل من جنود الشيعة عشرين ألفًا، ثم أقام بها مدة جدَّد عمارتها، وأصلح ما تهدم من أسوارها، وعين لها وزيرًا، وكان هذا السلطان يباشر الحروبَ بنفسه، ثم تم الاتفاق بين الدولتين على أن تسترد إيران مدينة إيريفان وأن تتخلى عن مدينة بغداد."},{"id":3896,"title":"مقتل الصدر الأعظم طيار محمد باشا رئيس الوزراء بالدولة العثمانية .","date":["العام الهجري :1048","الشهر القمري : شعبان","العام الميلادي :1638"],"text":"هو الصدر الأعظم طيار محمد باشا بن أوجار مصطفى باشا رئيس وزراء الدولة العثمانية. ولد في لاديك قرب البحر الأسود، وتولى الصدارةَ العظمى لفترة وجيزة في عهد السلطان مراد الرابع, لقِّب بالطيار لسرعته في العمليات الحربية. قُتل طيار محمد باشا أثناء حصار العثمانيين لبغداد التي استولى عليها الإيرانيون منذ عام 1624م. وكان طيار هو رابع رئيس وزراء عثماني يُقتَل في ساحة الحرب، وكان والده أوجار مصطفى باشا قد قُتل قبل سنوات برصاصة إيرانية أثناء حصار بغداد أيضًا."},{"id":3897,"title":"توقيع معاهدة صلح بين الدولة العثمانية والدولة الصفوية .","date":["العام الهجري :1049","الشهر القمري : جمادى الأولى","العام الميلادي :1639"],"text":"تم توقيع معاهدة صلح بين الدولة العثمانية في عهد مراد الرابع والدولة الصفوية، وانقطعت بهذه المعاهدةِ كلُّ أسباب العداوة بين البلدين."},{"id":3898,"title":"وفاة السلطان العثماني مراد الرابع وتولي أخيه إبراهيم الأول .","date":["العام الهجري :1049","الشهر القمري : شوال","العام الميلادي :1640"],"text":"هو السلطان مراد الرابع بن أحمد بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول، هو السلطان العثماني السابع عشر، ولد بإستانبول سنة 1021 جلس للحكم بعد عمه باتفاق من الأركان على عزل عمه مصطفى الأول، يوم الأحد الرابع عشر ذي القعدة سنة 1032 وله من العمر أحد عشر عامًا، فبايعه الأعيان، ثم فرق إنعامات الجلوس عليهم, وقد عمل السلطان مراد على استعادة هيبة الدولة وقوتها، فتولى هو ووزراؤه قيادة الجيوش وحقق عددًا من الانتصارات, وكان السلطان مراد يجيد التحدث باللغة العربية والفارسية فضلًا عن التركية، ويكتب قصائد تحت اسم مرادي. مرض السلطان مراد الرابع بن أحمد الأول سنة 1640م, وكان يُخشى عليه من الموت ولكن شفي, ثم مرض من جديد وتوفي في هذا العام؛ بسبب مرض النقرس بعد أن دام حكمه 16 سنة و11 شهرًا، ولم يكن قد عقب ولدًا ذكرًا، ولم يكن بقي من نسل آل عثمان غير أخيه إبراهيم بن أحمد الأول، فتولى الخلافة بعده، والذي كان مسجونًا مدة سلطنة أخيه، ولما توفي أخوه أسرع كبار المملكة إلى مكان الحبس ليخبروه بذلك، فعندما قدموا عليه ظنَّ أنهم قادمون لقتله، فخاف وذعر ولم يصدِّقْ ما قالوه له؛ ولذلك لم يفتح لهم باب السجن، فكسروه ودخلوا عليه يهنئونه، فظن أنهم يحتالون عليه للاطِّلاع على ضميره، فرفض قبَول الملك بقوله: إنه يفضل الوَحدةَ التي هو بها على مُلك الدنيا، ولَمَّا أن عجزوا عن إقناعه حضرت إليه والدته وأحضرت له جثة أخيه دليلًا على وفاتِه، وحين ذلك جلس على سرير السلطنة، ثم أمر بدفن جثة أخيه باحتفال وافر."},{"id":3899,"title":"السلطان العثماني إبراهيم الأول يسترد مدينة أزوف في بلاد القرم .","date":["العام الهجري :1051","العام الميلادي :1641"],"text":"افتتح السلطان إبراهيم الأول حروبه الخارجية بإرسال جيش جرار إلى بلاد القرم لمحاربة القوزاق الذين احتلوا مدينة آزوف (شمال البحر الأسود على بحر آزوف) فحاربهم العثمانيون وأبلَوا فيهم بلاء حسنًا واستردوا المدينةَ منهم بعد أن أحرقوها، وذلك سنة 1642."},{"id":3900,"title":"وفاة شيخ الإسلام يحيى بن بيرام مفتي الديار العثمانية .","date":["العام الهجري :1053","العام الميلادي :1643"],"text":"هو شيخ الإسلام يحيى بن زكريا بن بيرام مفتي الديار العثمانية في عصره. تركي الأصل، مستعرب. ولد سنة999 في إستانبول ونشأ بها. تولى قضاء الشام ثم نقل إلى قضاء مصر وعُزل، فولي قضاء بورصة، ثم قضاء أدرنة، ثم قضاء إستانبول, عُزل وولي مرارًا، وما زال يتنقل إلى أن توفي في الروم إيلي. وكان له في عصره شأن رفيع عند السلطان، جُمعت فتاواه في كتاب سُمِّي فتاوى يحيى، له نظم منه تخميس البردة."},{"id":3901,"title":"استعادة جزيرة كريت .","date":["العام الهجري :1055","العام الميلادي :1645"],"text":"كانت جمهورية البنادقة تهيمن على جزيرة كريت وعلى الحركة التجارية في بحر إيجة، مستغلين الصلح مع الدولة العثمانية، فعزم العثمانيون على تدمير نفوذ البنادقة في الشرق، فجُهِّزت الجيوش والأسطول وأُعلنت الحرب على البنادقة، واعتقل جميع البنادقة في طول البلاد وعرضها، وأُمر بمصادرة أموالهم وممتلكاتهم، ثم أمر السلطان إبراهيم بتجهيز عمارة بحرية قوية لفتح جزيرة كريت لأهمية موقعها الجغرافي الحربي عند مدخل بحر أرخبيل اليونان، ولتوسطها في الطريق بين الآستانة وولاية الغرب، فجُهزت الدونانمة وسارت باحتفال زائد تحت قيادة من يدعى يوسف باشا إلى أن ألقت مراسيها أمام مدينة خانية أهم ثغور الجزيرة في 29 ربيع الآخر من هذه السنة، وافتتحها بدون حرب تقريبًا؛ لعدم وصول الدونانمة البندقية إليها في الوقت المناسب، فانتقم البنادقة بحرق ثغور بتراس وكورون ومودون من بلاد مورة، ويقال إن السلطان أراد في مقابلة ذلك قتل جميع النصارى لولا معارضة المفتي أسعد زاده أبي سعيد أفندي."},{"id":3902,"title":"غزو الشريف زيد بن محسن أمير مكة بلاد نجد .","date":["العام الهجري :1057","العام الميلادي :1647"],"text":"غزا الشريف زيد بن محسن أمير مكة بلاد نجد، ونزل روضة سدير، وقتل رئيسها: محمد بن ماضي، وولى عليها: رميزان بن غشام، من آل بوسعيد"},{"id":3903,"title":"انتصار الأسطول العثماني على البنادقة في معركة أيبسارا البحرية .","date":["العام الهجري :1057","الشهر القمري : شعبان","العام الميلادي :1647"],"text":"انتصر الأسطول العثماني بقيادة المشير عمار زاده محمد باشا على البنادقة في معركة أيبسارا البحرية أثناء فتح العثمانيين لجزيرة كريت الواقعة في البحر المتوسط."},{"id":3904,"title":"خلع السلطان العثماني إبراهيم الأول وتولية ابنه محمد الرابع .","date":["العام الهجري :1058","الشهر القمري : رجب","العام الميلادي :1648"],"text":"أراد السلطان إبراهيم الأول أن يفتِكَ برؤوس الانكشارية المعارضين له، فعلموا بذلك فتآمروا على عزله وتولية ابنه الصغير محمد الذي لم يزِدْ عمره عن السابعة، فقاموا بخلعه بعد أن امتدَّ حكمه 8 سنوات و9 أشهر، ثم تمَّت تولية ابنه محمد الرابع، فلما أراد الخيَّالة السباهي أن يعيدوا السلطان المخلوع إبراهيم وعلمت الانكشارية بذلك، قتلوه, وقيل إن الذي عزله والدتُه السلطانة كوسم مهبيكر ثم تآمرت على قتله."},{"id":3905,"title":"انهيار النفوذ البرتغالي في مسقط على أيدي اليعاربة .","date":["العام الهجري :1060","العام الميلادي :1649"],"text":"انهار النفوذ البرتغالي في مسقط على أيدي اليعاربة؛ مما شجع العرب على العودة إلى سواحل الخليج العربي بعد أن انحسرت موجات هجرتهم خلال فترة الوجود العسكري البرتغالي، والتي استمرت نحو 190 عامًا، فكان انهيار النفوذ البرتغالي في الخليج دافعًا لاستئناف الهجرات القبلية نشاطها، والتي أسهمت بدورها في تأسيس الكيانات السياسية في الخليج العربي."},{"id":3906,"title":"مقتل السلطانة كوسم مهبيكر أشهر نساء الدولة العثمانية .","date":["العام الهجري :1061","الشهر القمري : رمضان","العام الميلادي :1651"],"text":"السلطانة \"كوسم مهبيكر\" واسمها الحقيقي \"أناستاسيا\" وُلدت في اليونان، وقيل إنَّها ولدت في البوسنة عام 999هـ, وهي من أشهر النساء في التاريخ العثماني, قيل إنها أُرسلت من اليونان إلى إستانبول من قبل والي البوسنة، ولما دخلت أناستاسيا الإسلام غيَّرت اسمها لاسم \"كوسِم\". وسُميت باسم \"ماه بيكر\" بفضل حُب السلطان العثماني أحمد الأول لها، الذي تزوجها بعد أن أسلمت, وقد تولى اثنين من أبنائها السلطنة: مراد الرابع، وإبراهيم الأول، وكذلك حفيدها محمد الرابع. وكانت نائبةَ السلطنة عن حفيدها محمد الذي لم يبلغ السابعة من عمره، لم تتردد في عزل ابنها إبراهيم عن السلطنة والتآمر لقتله؛ لعشقها للسلطنة والحياة السياسية، عُرفت بأعمال الخير، كبناء المساجد، وينابيع المياه، وتسديد ديون المساجين لإطلاق سراحهم من السجن. لما أرادت السلطانة كوسم أن تستبدل بحفيدها محمد الرابع حفيدًا آخر، انزعجت السلطانة خديجة تارخان أم السلطان محمد الرابع من ذلك، ولم تكن مطمئنة من كوسِم سلطان، فأمرت باغتيالها, فقُتِلَت خنقًا عن عمر يناهز 62 عامًا، ودُفنت بجوار قبر زوجها السلطان أحمد."},{"id":3907,"title":"تولي خديجة تارخان نيابة السلطنة في الدولة العثمانية .","date":["العام الهجري :1061","الشهر القمري : رمضان","العام الميلادي :1651"],"text":"تولَّت خديجة تارخان نيابة السلطنة في الدولة العثمانية نيابةً عن ابنها الصغير محمد الرابع، وهي من أصل أوكراني، وكان عمرها آنذاك 24 عامًا، واستمرت نيابتها حتى سنة 1066، عندما صعد كوبريلي محمد باشا إلى رئاسة الوزارة. وقد توفيت خديجة عن عمر يناهز الـ 56 عامًا سنة 1683م."},{"id":3908,"title":"وفاة محمد الأصغر ملك السعديين وتولي أحمد الثاني .","date":["العام الهجري :1064","العام الميلادي :1653"],"text":"هو السلطان محمد الأصغر بن زيدان ابن المنصور أحمد الذهبي ملك السعديين في المغرب الأقصى, ويلقَّب بالشيخ. لما قتل السلطان الوليد سنة 1045 اختلف الناس فيمن يقدمونه للولاية عليهم، ثم أجمع رأيُهم على مبايعة أخيه محمد الشيخ وإلقاء القيادة إليه، فأخرجوه من السجن، وكان أخوه الوليد قد سجنه إذ كان يتخوَّف منه الخروج عليه، فبويع بمراكش يوم الجمعة الخامس عشر من رمضان سنة 1045 ولما بويع سار في الناس سيرةً حميدة وألان الجانب للكافة، وكان متواضعًا في نفسه صفوحًا عن الهفوات متوقفًا عن سفك الدماء مائلًا إلى الراحة والدَّعَة متظاهرًا بالخير ومحبة الصالحين، إلا أنه كان منكوس الراية مهزوم الجيش؛ وبسبب ذلك لم يصفُ له مما كان بيد أبيه وإخوته إلا مراكش وبعض أعمالها، وبعد وفاته تولى أحمد الثاني بن العباس أبي مروان خلفًا له."},{"id":3909,"title":"ثورة قاطرجي أوغلي في الأناضول ضد العثمانيين .","date":["العام الهجري :1066","العام الميلادي :1655"],"text":"قامت ثورة في الأناضول بزعامة قاطرجي أوغلي، ودعمه كورجي يني؛ اللذان انتصرا على والي الأناضول أحمد باشا، ثم توجَّها نحو إستانبول، ولكنهما اختلفا فسلمت العاصمة منهما؛ لاختلافهما، وانتصر عليهما السلطان محمد الرابع لذلك الخلاف، فقتل كورجي يني، وطلب قاطرجي أوغلي العفو، وتسلَّم ولاية القرمان، ورغم انتهاء الثورة لم تتحسن أوضاع الدولة الداخلية ولا الخارجية."},{"id":3910,"title":"تولي كوبريلي محمد باشا رئاسة الوزراء في الدولة العثمانية .","date":["العام الهجري :1066","الشهر القمري : ذي القعدة","العام الميلادي :1656"],"text":"تولى كوبريلي محمد باشا رئاسة الوزراء في الدولة العثمانية، الذي حاول انتشال الدولة من حالة التدهور، فتسلم مقاليد أمور الدولة من نائبة السلطنة خديجة تارخان، واستمر دور عائلة \"كوبريلي\" في الدولة مدة 27 عامًا حتى عام 1683م. واستطاعت هذه الأسرة أن تُنقذ الدولة العثمانية بفضل الله تعالى من أزمات كبيرة كادت تعصف بها. واستمرت رئاسة \"كوبريلي\" للوزراء حتى أكتوبر 1661م."},{"id":3911,"title":"وفاة المؤرخ التركي حاجي خليفة .","date":["العام الهجري :1068","العام الميلادي :1657"],"text":"هو المؤرِّخ التركي مصطفى بن عبد الله الحلبي المعروف بحاجي خليفة، ولد سنة 1017هـ / 1608م، وحفظ القرآن، ودَرس العربية والفقه والحساب، واهتم بالتاريخ والجغرافيا. وأبوه من رجال الجند، استُخدم كاتبًا في نظارة الجيش بالأناضول حتى أصبح رئيس الكُتاب، ثم عاد إلى الآستانة وتفرغ للعلم ولقب خليفة منذ كان بالآستانة، اشتهر بمؤلَّفه النافع: كشف الظنون عن أسامي الكتب والفنون، الذي يحوي على 14500 اسم كتاب، ويعتبر خزانة علم وأدب وتاريخ، وله مصنفات أخرى منها: تحفة الأخبار في الحِكم والأمثال والأشعار، وله سُلَّم الوصول إلى طبقات الفحول، وله تحفة الكبار في أسفار البحار."},{"id":3912,"title":"ثورة المسلمين الأندلسيين الثانية في أسبانيا .","date":["العام الهجري :1069","العام الميلادي :1658"],"text":"بدأت اضطرابات محدودة من قِبَل المسلمين في جبل البشرات تمكَّن جنود مركيز مندخار (الحاكم العسكري) من إنهائها بسرعة, ومكَّن الهدوء النسبي الذي لحق ذلك بدء انتقال أعداد من شبان مدينة غرناطة إلى الجبال سرًّا للتدرُّب على استخدام السلاح. وفي الثالث والعشرين من ديسمبر اعتقد الثوارُ أن عددهم كان كافيًا للقيام بالخطوة التالية فشنُّوا هجومًا مباغتًا على مدينة غرناطة فيما كانت حاميتها تستعد للاحتفال بعيد الميلاد. وتمكَّن الثوار بقيادة فراس بن فراس من التوغل في المدينة والاشتباك مع جنود مركيز مندخار إلا أنهم لم يتمكنوا من أخذ المدينة، فانسحبوا وعادوا إلى البشرات بعد إيقاع خسائر كبيرة بجنود الحامية، وبدؤوا بإزالة كل أشكال السلطة والكنيسة القشتالية في المراكز المحررة. وحيال هذا التطور أصدر ملك أسبانيا فيليب الثاني أوامره إلى مركيز مندخار بإخماد ثورة البشرات، فقاد جيشًا من حوالي أربعة آلاف جندي إلى الجبال إلا أنه لم يشتبك معهم، وبدأ بدلًا من ذلك مفاوضات لوقف الثورة آخذًا على عاتقه محاولة إقناع الملك فيليب الثاني برفع الضغوط عن الأندلسيين. وأوقف الأندلسيون العمليات العسكرية فيما بدأ المركيز اتصالاته لإقناع الملك بإعطاء الثوار فرصة، إلا أن فيليب رفض الفكرة وأمر المركيز بقمع الثورة وضرب زعمائها ليكونوا عبرة لغيرهم ليس فقط في الجنوب وإنما في ممالكه الأخرى قاطبة. وفي هذه الأثناء أقدم بعضُ جنود المركيز على مذبحة في مدينة جبيل راح ضحيتها عدد من الأندلسيين، وتعرضت مدينة لورة إلى هجمات مماثلة، وفقد المركيز السيطرةَ على جنوده فأخذ هؤلاء يمارسون أعمال القتل بلا حساب فتحرَّك الأندلسيون بسرعة وبسطوا سيطرتَهم على البشرات. وفي غرناطة نفسها وصلت إلى الحامية إشاعات عن قيام الثوار الأندلسيين بقتل 90 قسيسًا و1500 قشتالي، فهاجم الجنود سجن البيازين وذبحوا مئة وعشرة أندلسيين كانوا فيه. وأمام انفلات الوضع أقرَّ مركيز مندخار بعجزه عن السيطرة على الوضع، ووضع نفسه تحت إمرة فيليب الثاني. وكانت نار الثورة بدأت تستعر بسرعة وتنتشر في مناطق جديدة في الجنوب عندما بدأ الملك تدارُس الوضع مع مستشاريه العسكريين. وفي هذه الأثناء بدأ العثمانيون يحققون الانتصار تلو الآخر في البحر الأبيض المتوسط، وراحوا يهددون شواطئ ممالكه هناك. وفي تلك السنة أيضًا اندلعت الثورة في قطالونيا وقطعت أساطيل البروتستانت الطرق البحرية إلى خليج بسقاية، وخشي فيليب الثاني أن يستفحِلَ خطر الثورة ويستغل العثمانيون استمرارها لمهاجمة صقلية والجزائر الشرقية وربما الجنوب الأندلسي، فاختار لمهمة القضاء على الثورة أخاه دون خوان النمسوي، وأوصى فيليب الثاني دون خوان بضرورة اتخاذ قرارات المجلس بالإجماع، وإذا لم يتحقق هذا يجب عليه العودة إليه لاتخاذ القرار النهائي. وكان على دون خوان التحرُّك بسرعة للقضاء على الثورة خوفًا من انتقالها إلى الأندلسيين في أرغون. ولما عرض دون خوان على أعضاء المجلس هذا الرأي أخذوا به، لكنَّ مركيز مندخار عارضه وأعرب عن اعتقاده أن التفاوض وليس الحرب هو طريق إنهاء الأزمة. وأمام هذا الموقف نشد المجلس موافقة فيليب الثاني، فكتب إليه دون خوان رسالة مُطوَّلة أوصى فيها بالحزم في التعامل مع الثوار، وتعهَّد لأخيه بالقضاء على الثورة سريعًا إن أعطاه الصلاحيات وأطلق يديه. لكنه تردد ولم يجبه، فاستغل الأندلسيون تردُّد الملك فالتحق بالثوار عدد كبير من المتطوعين حتى صار قوامهم نحو عشرة آلاف مقاتل، وبدؤوا يشنون الهجمات على مواقع القوات القشتالية، فامتلكوا عددًا منها، ثم نقلوا الحرب إلى مناطق قريبة من مدينة غرناطة ودارت معارك بينهم وبين القشتاليين قرب الأسوار. وسرت في القشتاليين المخاوفُ من انقلاب الأندلسيين الغرناطيين عليهم فتشدَّدوا في معاملتهم؛ مما أدى إلى فرار بعضهم من المدينة والالتحاق بمعاقل الثوار. وخلال فترة قصيرة اتسعت الرقعة التي بسط عليها الثوار نفوذَهم حتى شملت معظم المناطق المحيطة بمدينة غرناطة. ووصلت أخيرًا أوامر فيليب الثاني آخذًا في الاعتبار معظم توصيات أخيه، لكنَّه أمر بشطر القوات التي تجمَّعت شطرين أسند قيادة الأول إلى مركيز مندخار، والثاني إلى منافسه مركيز بلش مالقه، لكنه حظر في الوقت نفسِه على دون خوان الاشتراك في أي عمليات عسكرية. واعتبر باقي أعضاء المجلس هذا التكليف تشكيكًا من الملك بمركيز مندخار فانهزَّت الثقة به وخضعت قراراته للمساءلة وتصرفاته للمراقبة!"},{"id":3913,"title":"طرد البرتغاليين من مسقط وعُمان .","date":["العام الهجري :1069","العام الميلادي :1658"],"text":"بدأت الثورةُ في الخليج العربي عمومًا وفي هرمز خصوصًا ضد البرتغاليين من بداية القرن العاشر الهجري، واستمرت بين مد وجزر حتى كانت النهاية في طرد البرتغاليين من مسقط وعمان، وكان الأثر الأكبر في ذلك هو تنامي قوة العرب العمانيين من أسرة اليعاربة التي قُدِّر لها أن تحسم الصراع لصالح العرب وتقضي على الإمبراطورية البرتغالية، وبرزت وحدة الشعب العماني في عهد هذه الأسرة التي نمت وترعرعت بسبب وجود المستعمر البرتغالي على أرض عمان، والتخلص منه."},{"id":3914,"title":"وفاة السلطان أحمد بن عبد الملك ملك السعديين بالمغرب .","date":["العام الهجري :1069","العام الميلادي :1658"],"text":"هو السلطان أحمد العباس بن أبي مروان عبد الملك، ملك السعديين في المغرب الأقصى، قتله أخوه، ويعتبر هو آخر الملوك السعديين فرع الحسنيين، وكان من أسباب نهاية هذا الفرع من السعديين الأشراف تنافس الأمراء على الحكم والاستعانة بخصوم الدولة سواء الأسبان والبرتغال أو الأتراك. وبدأت بعد عهد الأشراف دولة العلويين في مراكش بزعامة الرشيد بن محمد."},{"id":3915,"title":"تعيين العثمانيين مدينة بوخارست عاصمة لرومانيا .","date":["العام الهجري :1070","الشهر القمري : صفر","العام الميلادي :1659"],"text":"عين السلطان العثماني محمد الرابع مدينة بوخارست كعاصمة لرومانيا، وأصبحت بوخارست منذ ذلك التاريخ هي العاصمةَ الرومانية."},{"id":3916,"title":"استيلاء القائد العثماني كوسه على قلعة فيرتا الألمانية .","date":["العام الهجري :1070","الشهر القمري : ذي القعدة","العام الميلادي :1660"],"text":"تمكَّن القائد العثماني البحري كوسه علي باشا من الاستيلاء على قلعة فيرتا الألمانية بعد حصار دام 45 يومًا، وغنم العثمانيون 700 مدفع من القلعة."},{"id":3917,"title":"البرتغال تتخلى عن طنجة للإنجليز  .","date":["العام الهجري :1071","العام الميلادي :1660"],"text":"كان البرتغاليون يحتلون طنجة قرنين من الزمان، ثم إن الأميرة كاترينا البرتغالية قدَّمت طنجة صداقًا لزوجها تشارلز الثاني ملك إنكلترا، فأصبحت طنجة تحت النفوذ الإنكليزي."},{"id":3918,"title":"وفاة الصدر الأعظم كوبريلي محمد علي باشا .","date":["العام الهجري :1072","الشهر القمري : ربيع الأول","العام الميلادي :1661"],"text":"هو الصدر الأعظم محمد علي باشا كوبريلي، وهو أشهر رئيس وزراء للدولة العثمانية في أدرنة, وعلى الرغم من كبر سنه كان قوي الشخصية والإرادة، عظيم الهمة، يميل إلى الشدة والترهيب فيما يتصل بأمن الدولة وسلطانها، فانتظمت أمور الدولة الداخلية، وضرب على أيدي الانكشارية وأعادهم إلى احترام النظام والانشغال بعملهم، ومنعهم من التدخل فيما لا يعنيهم من شؤون السياسة. وفي الوقت نفسه حقق للدولة بعض الانتصارات الخارجية، فهزم البنادقةَ وأخذ منهم جزيرة لمنوس وجزرًا أخرى. وكان البنادقة قد استولوا على هذه الجزر واحتلوا مدخل مضيق الدردنيل، وفرضوا حصارًا بحريًّا على الدولة، ومنعوا دخول المُؤَن والغذاء إلى إستانبول، ولولا نجاح الصدر الأعظم كوبريلي محمد في فك هذا الحصار لتعرضت الدولة إلى خطر فادح. توفي عن عمر يناهز 83 عامًا، وبعد فترة رئاسة استمرت 5 سنوات، وخلفه في الوزارة ابنه زاده فاضل أحمد باشا كوبريلي."},{"id":3919,"title":"تراجع قوة الدولة العثمانية أمام دول الغرب .","date":["العام الهجري :1073","العام الميلادي :1662"],"text":"بوفاة الصدر الأعظم \"أحمد كوبريلي\" العام الماضي ضعف النظام العثماني، وتمكنت دول أوربا خلال السنوات القادمة من تحقيق انتصارات على الدولة العثمانية, فهاجمت النمسا بلاد المجر، واغتصبت قلعة نوهزل ومدينة بست ومدينة بودا، وأغار ملك بولونيا على ولاية البغدان، وأغارت سفن البندقية على سواحل المورة واليونان، واحتلت أثينا وكورنثة عام 1097هـ وغيرها من المدن. وتذكر كتب التاريخ أن العلماء ورجال الدولة بسبب هذا التدهور قد اتَّفقوا على عزل السلطان محمد الرابع فعُزِل عام 1099هـ."},{"id":3920,"title":"إعلان الدولة العثمانية الحرب على ألمانيا .","date":["العام الهجري :1073","الشهر القمري : رمضان","العام الميلادي :1663"],"text":"أعلنت الدولة العثمانية الحرب على ألمانيا بعد 56 عامًا من معاهدة سيتفاتوروك التي أوقفت الحرب السابقة بين الجانبين، وكان سبب الحرب هذه المرة هو بناء الألمان قلعة حصينة على الحدود مع الدولة العثمانية."},{"id":3921,"title":"العثمانيون يحصارون قلعة نوهزل النمساوية والاستيلاء عليها .","date":["العام الهجري :1074","الشهر القمري : محرم","العام الميلادي :1663"],"text":"كان الصدر الأعظم محمد كوبريلي الذي توفي عام 1072هـ أعاد للدولة العثمانية هيبتها، ولما خلفه ابنه أحمد سار سيرةَ أبيه، فرفض الصلحَ مع النمسا والبندقية وسار على رأس جيش لقتال النمسا، وتمكن من أن يفتح أعظم قلعة في النمسا وهي قلعة نوهزل شرقي فيينا، ومع أن هذه القلعة كانت مشهورة في جميع أوروبا بالمناعة وعدم إمكان أي أحد التغلب عليها وفتحها، فقد اضطر كوبريلي أحمد باشا حاميتَها إلى التسليم بشرط خروج من بها من الجنود بدون أن يمسهم ضرر، تاركين ما بها من الأسلحة والذخائر، وأخلوها فعلًا في 25 صفر سنة 1074 بعد البدء في حصارها بستة أسابيع؛ ولذلك اضطربت أوربا بأجمعها لهول هذا الخبر الذي دوَّى في آذان ملوك أوربا ووزرائها، وكان هذا الفتح المبين أشد تأثيرًا على ليوبولد إمبراطور النمسا أكثر من غيره؛ لدخول الجيوش العثمانية في بلاده وانتشارها في إقليمي مورافيا وسيليزيا فاتحين غازين حتى خُيِّل له أن السلطان سليمان القانوني قد بُعث من جديد لفتح عاصمة دولته!!"},{"id":3922,"title":"استيلاء العثمانيين على قلعة \"أويفار\" الخاضعة للألمان .","date":["العام الهجري :1074","الشهر القمري : صفر","العام الميلادي :1663"],"text":"تمكن العثمانيون من الاستيلاء على قلعة \"أويفار\" الواقعة شمال غرب بودابست بعد 37 يومًا من الحصار. وقد كانت القلعة خاضعة للألمان، وتعدُّ أقوى وأحصن قلاع أوربا، وكان الاستيلاء عليها فاتحةً لاستسلام 30 قلعة ألمانية للدولة العثمانية!"},{"id":3923,"title":"استيلاء العثمانيين على قلعة \"يني قلعة\" .","date":["العام الهجري :1074","الشهر القمري : ذي القعدة","العام الميلادي :1664"],"text":"تمكن العثمانيون من الاستيلاء على قلعة \"يني قلعة\" الحصينة داخل الحدود الألمانية، والتي تسبب تشييدها في نشوب الحرب بين الجانبين في إبريل 1663م."},{"id":3924,"title":"استمرار حكم العلويين الأشراف في المغرب بعد السعديين .","date":["العام الهجري :1075","العام الميلادي :1664"],"text":"كان وجود الأشراف في المغرب قديمًا, لكن لم يتسنَّ لهم تسلم القيادة إلا في هذه الفترة التي مثَّل الشرفاء فيها سلالة السعديين، والتي جاءت من الجزيرة العربية أواخر القرن الثامن الهجري، وأول من وصل العرش منهم هو محمد المهدي القائم بأمر الله بن عبد الرحمن بن علي، وهو الذي أخرج الوطاسيين نهائيًّا من فاس، ومن جهة أخرى لم تنقطع الهجمات الصليبية من البرتغال والأسبان على السواحل، ومع ذلك استطاع السعديون الحسنيون أن ينشروا نفوذهم في جميع أنحاء المغرب مانعين العثمانيين من مدِّ نفوذهم إليها، ثم إن أمر الأسرة بدأ يضمحل، وخاصة بعد وفاة أحمد العباس بن عبد الملك سنة 1064هـ وكان هناك فرع آخر في المغرب من الأسرة نفسها أعلن دعواه في العرش، ثم إن ولدي محمد الثاني بن محمد الشريف، وهما الرشيد وأبو النصر إسماعيل، أنقذا المغرب من الفوضى وأعاد ثانيهما على الأخص سلطة الشرفاء إلى جميع البلاد بعد أن قضى على سلطات الحكام الصغار وعلى تمردات البربر."},{"id":3925,"title":"واقعة سان جوتار وعقد صلح مع النمسا .","date":["العام الهجري :1075","الشهر القمري : محرم","العام الميلادي :1664"],"text":"بعد استيلاء العثمانيين على قلعة نوهزل النمساوية، وسَّطَ ليوبولد إمبراطورُ النمسا البابا إسكندرَ السابِعَ في طلبه المساعدة له من ملك فرنسا- الذي كان قد عرض على ليوبولد قبل حصار العثمانيين لقلعة نوهزل إمدادَه بأربعين ألفًا من الألمان المحالفين له، فأبى خوفًا من إظهار الضعف- فسعى البابا جهدَه لدى ملك فرنسا حتى قَبِلَ بإرساله ستة آلاف جندي فرنساوي وأربعة وعشرين ألفًا من محالفيه الألمان، وانضم هذا الجيش إلى الجيش النمساوي تحت قيادة الكونت دي كوليني، وابتدأت المناوشات بين الجيشين المتحاربين، فقُتل الكونت دي القائد العام النمساوي، وخلفَه القائدُ مونت كوكوللي، وكان قد انضم إلى الجيش الفرنساوي عدد عظيم من شبان الأشراف, وفي بداية القتال كان النصر حليفًا للعثمانيين فاحتل كوبريلي أحمد باشا مدينة سرنوار وعسكر على شاطئ نهر يقال له نهر راب والأعداء معسكرون أمامه، وبعد أن حاول كوبريلي عبور النهر صده الجيش النمساوي الفرنساوي, فجمع كل قواه في يوم 8 محرم سنة 1075 وعبر النهر عنوة وانتصر على قلب جيش العدو، ولولا تدخل الفرنساويين وخصوصًا الأشراف منهم، لتم النصر للعثمانيين, وانتهى اليوم بدون انتصار تام لأحد الفريقين؛ فإن العثمانيين حافظوا على مراكزهم بدون تقدم للأمام، وسميت هذه الواقعة بواقعة سان جوتار نسبة لكنيسة قديمة حصلت الحرب بالقرب منها، وبعد تبادل المخابرات بين الطرفين توصلا للصلح وأُبرمت معاهدة بينهما أهم ما نصت عليه إخلاء الجيش العثماني لإقليم ترنسلفانيا وتعيين أبافي حاكمًا عليها تحت سيادة الدولة العثمانية، وتقسيم بلاد المجر بين الدولتين بأن يكون للنمسا ثلاث ولايات، وللباب العالي أربعة، مع بقاء حصني نوفيجراد ونوهزل تابعين للدولة العلية العثمانية!"},{"id":3926,"title":"وقوع اشتباك بين الجيش الألماني ومقدمة الجيش العثماني .","date":["العام الهجري :1075","الشهر القمري : محرم","العام الميلادي :1664"],"text":"اشتبك الجيش الألماني المكون من 60 ألف جندي مع مقدمة الجيش العثماني المكونة من 10 آلاف جندي، وتمكن من إفنائها في حربٍ غير متكافئة بعد سبع ساعات من القتال قُتِلَ خلالها 10 آلاف ألماني!"},{"id":3927,"title":"عودة الجيش العثماني إلى أدرنة لقتال الألمان .","date":["العام الهجري :1075","الشهر القمري : شوال","العام الميلادي :1665"],"text":"عاد الجيش العثماني بقيادة رئيس الوزراء فاضل أحمد باشا إلى أدرنة بعد مغادرتها لمدة سنة و3 أشهر لقتال ألمانيا؛ حيث انتهت الحرب بين الجانبين بتوقيع معاهدة \"فاشفار\" على بعد 3 كم عن النمسا."},{"id":3928,"title":"تولي \"كوبريلي فاضل باشا\" قيادة الحملة العثمانية لفتح جزيرة كريت .","date":["العام الهجري :1076","الشهر القمري : ذي القعدة","العام الميلادي :1666"],"text":"تولى رئيس الوزراء \" كوبريلي فاضل أحمد باشا\" قيادة الحملة العثمانية لفتح جزيرة كريت، وقد استمر \"فاضل\" في الجزيرة طيلة 3 سنوات ونصف سنة حتى تم فتح كريت."},{"id":3929,"title":"رفع رئيس الوزراء فاضل أحمد باشا الحصار عن \"قلعة كاندية\" .","date":["العام الهجري :1078","الشهر القمري : ربيع الآخر","العام الميلادي :1667"],"text":"يعتبر حصار قلعة كاندية المنيعة في جزيرة كريت أطول حصار في التاريخ، كان العثمانيون قد قضوا سنة 1055 ثلاثة أشهر لفرض الحصار على مدينة كاندية، بقطع إمدادات المياه، وتعطيل الممرات البحرية البندقية إلى المدينة، وقاموا بقصف المدينة دون تأثير يذكر. البنادقة بدورهم حاصروا الدردنيل لمنع وصول الإمدادات العثمانية لجزيرة تكريت, وتلقَّت جمهورية البندقية المزيدَ من المساعدات من الدول الأوروبية الغربية الأخرى خلال مدة الحصار التي تجاوزت ثلاثًا وعشرين سنة قتل خلالها 8 آلاف جندي من البنادقة, وفي هذا العام تمكن القائد العثماني رئيس الوزراء فاضل أحمد باشا من رفع الحصار عن القلعة بعد أن قَبِلت البندقية بتسليم المدينة وخروج قواتها منها بدون أسلحة أو ذخيرة."},{"id":3930,"title":"وفاة الشيخ سليمان التميمي جد الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1079","العام الميلادي :1668"],"text":"هو العلَّامةُ الفقيهُ الشيخ أبو محمد سليمان بن علي بن محمد بن أحمد بن راشد بن بريد بن مشرف الوهيبي الحنظلي التميمي، جَدُّ الإمام المجدِّد محمد بن عبد الوهاب, وعالمُ الدِّيار النجدية في عصره ومُفتيها. قيل إنه وُلد في بلدة أشيقر ونشأ فيها وقرأ على علمائها, واشتهر بالورع والتواضع وغمط النفس, والعدل في أقضيته، وكان قويًّا في الحق، لا تأخذه في الله لومة لائم، وبعد أن برز وبرع في العلم واشتهر، طَلَبَه أهالي روضة سدير؛ ليكون قاضيًا لديهم، فأجابهم، وانتقل من مسقط رأسه أشيقر إلى روضة سدير، وأخذ في تعليم الناس، والقضاء بينهم، فحُمِدَت سيرته، وانتفع به أهلُها كثيرًا. ثم انتقل بعد ذلك إلى العُيينة، حيث تولى القضاء فيها، وحُمِدَت سيرته فيها أيضًا, وصنف المنسك المشهور به، وكان عليه اعتماد الحنابلة في المناسك. وله فتاوى تبلغ مجلدًا ضخمًا."},{"id":3931,"title":"عقد الدولة العثمانية معاهدة مع البندقية .","date":["العام الهجري :1080","الشهر القمري : ربيع الآخر","العام الميلادي :1669"],"text":"وقعت الدولة العثمانية معاهدة من 18 مادة تم بمقتضاها انتقال قلعة \"كاندية\" الحصينة في جزيرة كريت إلى الدولة العثمانية، إضافة إلى 1100 مدفع كانوا في القلعة، وأن تحصل تركيا على كامل جزيرة كريت، وبذلك تنتهي الحرب العثمانية مع البندقية التي استمرت 24 عامًا."},{"id":3932,"title":"قيام حكم البايات في الجزائر كما حصل من قبل في تونس .","date":["العام الهجري :1081","العام الميلادي :1670"],"text":"كان النظامُ في الدولة العثمانية في هذه الولايات التابعة لها أن يكون هناك والٍ عثماني هو الباشا، يحكم تلك الولايةَ ويكون تحته أعوانٌ ويكون التصرفُ للباشا، ثم تغيَّرَ الوضع فأصبح نظامُ الباي، وذلك أن الرجل الذي يكون واليًا ممثلًا للخليفة في هذه الولاية هو الباي (بيلرباي) وليس شرطًا أن يكون عثمانيًّا، ويساعده ديوانٌ استشاريٌّ مؤلَّفٌ من  عسكريين يمثِّلون الفِرَق العسكرية في الولاية، ويلقَّبُ كل منهم بالداي، إضافة إلى موظف الشؤون الماليَّة. وقد طبق هذا النظام من قبل في تونس عام 1017 هـ."},{"id":3933,"title":"غزو براك بن غرير زعيم بني خالد بلاد نجد .","date":["العام الهجري :1081","العام الميلادي :1670"],"text":"غزا براك بن غرير زعيم بني خالد بلاد نجد من مركزه في الأحساء، واستمرت حملاته عليها لفترة؛ مما أدى إلى تزايد نفوذه والتضييق على العثمانيين ونفوذهم بالمنطقة."},{"id":3934,"title":"وفاة الملك أبو العز الرشيد ملك العلويين بالمغرب وتولي أخيه إسماعيل .","date":["العام الهجري :1082","العام الميلادي :1671"],"text":"هو الملك أبو العز الرشيد بن محمد بن علي الحسني أول ملوك شرفاء مراكش من العلويين، وكان قد قاتل أخاه محمدًا الذي كان قد تسلم بعد وفاة أبيهما عام 1069هـ وكانت قاعدتهم سجلماسة، فلما أصبح الأمر للرشيد نقل العاصمة إلى مراكش؛ ولهذا عُدَّ هو أولَ ملوك العلويين في مراكش وتولى أخوه إسماعيل الملك خلفًا له."},{"id":3935,"title":"محاولة فرنسا تجديد الامتيازات في الدولة العثمانية .","date":["العام الهجري :1083","العام الميلادي :1672"],"text":"حاولت فرنسا التقرب من الدولة العثمانية، وتجديد الامتيازات، غيرَ أن الصدر الأعظم رفض ذلك، ثم حاولت فرنسا التهديدَ؛ حيث أرسل \"لويس الرابع عشر\" ملك فرنسا السفيرَ الفرنسي مع أسطول حربي، وهذا ما زاد الصدر الأعظم إلا ثباتًا، وقال: إن الامتيازات كانت منحة، وليست معاهدة واجبة التنفيذ, فتراجعت فرنسا أمام تلك الإرادة الحديدية واستعملت سياسة اللين والخضوع للدولة العثمانية، حتى جددت لها المعاهدات القديمة وأعادت لها امتياز حماية البيت المقدس عام 1084هـ."},{"id":3936,"title":"قيام الحرب بين الدولة العثمانية وبولندا وتوقيع معاهدة بين الطرفين .","date":["العام الهجري :1083","العام الميلادي :1672"],"text":"رغب القوزاق في التبعية إلى الدولة العثمانية فأعلنوا ذلك، وكانوا يقيمون في أوكرانيا والمناطق التي تقع إلى الشرق منها، وهذا ما أغضب بولونيا فأغارت على أوكرانيا التي طلبت النجدة من العثمانيين، وسار الخليفة محمد الرابع بنفسه على رأس جيش انتصر على البولونيين الذين طلبوا الصلح، فعقد ولم يمضِ على الحرب أكثر من شهر واحد، وقد اعترفت بولونيا فيه بأن أوكرانيا للقوزاق وأن إقليم بووليا في غرب أوكرانيا للدولة العثمانية، وفوق هذا الاعتراف تدفع بولونيا جزية قدرها مائتين وعشرين ألف بندقي ذهبًا، فتضايق الشعب البولوني من هذه المعاهدة التي عرفت باسم بوزاكس، فأعلن رفضه لها وسار القائد البولوني سوبيسكي بجيوش جرارة وقاتل العثمانيين، واستمرت المعارك سِجالًا بين الطرفين، ثم عادت المفاوضات فعُقد الصلح بين الطرفين وتنازل فيه ملك بولونيا إلى العثمانيين عما تنازل له سلفه باستثناء بعض المواقع."},{"id":3937,"title":"السلطان محمد الرابع يبدأ حملته السلطانية الأولى على بولونيا .","date":["العام الهجري :1083","الشهر القمري : صفر","العام الميلادي :1672"],"text":"بدأ السلطان محمد الرابع حملته الهمايونية السلطانية الأولى على بولونيا- بولندا-والتي استمرت 6 أشهر، تم خلالها افتتاح عدد من القلاع، وانتهت الحملة بتوقيع معاهدة بين الطرفين دفعت خلالها بولونيا ضريبة سنوية للعثمانيين."},{"id":3938,"title":"استيلاء الجيش العثماني على قلعة كاماينجو البولونية .","date":["العام الهجري :1083","الشهر القمري : جمادى الأولى","العام الميلادي :1672"],"text":"استطاع الجيش العثماني الاستيلاء على قلعة كاماينجو البولونية الحصينة الواقعة على نهر تورلا، بعد 9 أيام من الحصار."},{"id":3939,"title":"فتح القائد العثماني قبلان مصطفى باشا منطقة بودوليا .","date":["العام الهجري :1083","الشهر القمري : جمادى الأولى","العام الميلادي :1672"],"text":"استطاع القائد العثماني قبلان مصطفى باشا أن يفتح منطقة بودوليا، ويؤسِّس فيها إيالة \"كامانيجة\"، وكانت هذه المنطقة تابعة لبولونيا، لكنها تقع الآن في جمهورية أوكرانيا. وقد استمرت السيطرة العثمانية عليها حتى نوفمبر 1180م."},{"id":3940,"title":"إعلان الدول الأوربية الحرب على الدولة العثمانية .","date":["العام الهجري :1084","الشهر القمري : جمادى الأولى","العام الميلادي :1673"],"text":"أعلنت الدول الأوربية الحربَ على الدولة العثمانية، واستمرَّت هذه الحرب حتى عام 1686م، وعُرفت هذه السنوات في التاريخ العثماني بسنوات المصيبة, وكان هدف هذه الحملات هو إخراج المسلمين الأتراك من أوربا إلى آسيا, وأطلق البابا على هذه الحرب \"الحملة الصليبية الـ14 ضد الأتراك\"."},{"id":3941,"title":"تغلب الجيشِ البولوني على الجيش العثماني واستيلاؤه على خوتين .","date":["العام الهجري :1084","الشهر القمري : رجب","العام الميلادي :1673"],"text":"تمكن الجيش البولوني بقيادة \"سوبياسكي\" والمكون من 80 ألف جندي من الاستيلاء على خوتين الواقعة على نهر تورلا من العثمانيين بعد هزيمة الجيش العثماني المكون من 30 ألف جندي في معركة استمرت 3 ساعات."},{"id":3942,"title":"المعاهدة النهائية للامتيازات بين الدولة العثمانية وإنجلترا  .","date":["العام الهجري :1086","العام الميلادي :1675"],"text":"عقد السلطان محمد الرابع معاهدة جدَّد فيها الامتيازات التجارية الممنوحة لدولة إنكلترا وأضيف إليها بنود أخرى، وأطلق عليها اسم المعاهدة النهائية للامتيازات بين الإمبراطورية العثمانية وإنكلترا، وتُمثل هذه المعاهدة المرحلة الثانية في تاريخ الامتيازات في نَيل التاجر البريطاني حريةَ التجارة داخل البلاد العثمانية والتمتع بما يكفي حماية نفسه وماله."},{"id":3943,"title":"وفاة الصدر الأعظم العثماني زاده فاضل أحمد باشا كوبريلي  .","date":["العام الهجري :1087","الشهر القمري : رمضان","العام الميلادي :1676"],"text":"هو الصدر الأعظم زاده فاضل أحمد باشا ابن الصدر الأعظم محمد علي باشا كوبريلي رئيس الوزراء، وأحد رجالات الدولة العثمانية الكبار في القرن الحادي عشر الهجري، وأصغر من تولى رئاسة الوزراء في تاريخ الدولة العثمانية. توفي عن إحدى وأربعين سنة قضى منها خمس عشرة سنة في منصب الصدارة العظمى بكل أمانة وصدق سائرًا في ذلك على خطة والده محمد علي باشا, وتقلد منصب الصدارة بعده زوج أخته قرة مصطفى باشا، ولم يكن كفؤًا للسير في الطريق الذي رسمه كوبريلي الكبير وولده، بل اتبع مصلحته الذاتية وباع المناصب العالية والمعاهدات والامتيازات المجحفة بالدولة حالًا ومستقبلًا بدراهم معدودة."},{"id":3944,"title":"وفاة الشيخ المحدث علاء الدين الحصكفي مفتي الحنفية في دمشق .","date":["العام الهجري :1088","العام الميلادي :1677"],"text":"هو الشيخ المحدث محمد بن علي بن محمد الحصني، المعروف بعلاء الدين الحصكفي، الكثير الحفظ والمرويات، مفتي الحنفية في دمشق. مولدُه في دمشق سنة 1025. كان فاضلًا عالي الهمة، عاكفًا على التدريس والإفادة. من كتبه الدر المختار في شرح تنوير الأبصار في فقه الحنفية، وإفاضة الأنوار على أصول المنار في الفقه، والدر المنتقى شرح ملتقى الأبحر في الفقه، وشرح قطر الندى في النحو، وله تعليق على صحيح البخاري في مجلد. توفي في دمشق عن 63 سنة."},{"id":3945,"title":"رفع القائد العثماني شيطان إبراهيم باشا الحصار عن قلعة جهرين .","date":["العام الهجري :1088","الشهر القمري : جمادى الآخرة","العام الميلادي :1677"],"text":"رفع القائد العثماني شيطان إبراهيم باشا الحصار عن قلعة جهرين في أوكرانيا، وذلك بسبب المقاومة الكبيرة التي أبداها 60 ألف جندي روسي وأوكراني."},{"id":3946,"title":"وفاة ابن العماد الحنبلي .","date":["العام الهجري :1089","العام الميلادي :1678"],"text":"هو الشيخ أبو الفلاح عبد الحي بن أحمد بن العماد العكبري، مؤرخ وفقيه حنبلي وعالم بالأدب، ولد في دمشق سنة 1032 ونشأ بها، وقرأ القرآن الكريم على بعض الشيوخ، وطلب العلم مشمِّرًا عن ساعد الجد والاجتهاد، فأخذ عن أعلام الأشياخ، وأجلُّهم الشيخ أيوب الخلْوَتي الصوفي. وتلقى الفقهَ قراءة وأخذًا عن ابن فقيه فُصَّة مفتي الحنابلة بالشام في عصره، ثم رحل إلى القاهرة وأقام بها مدة طويلة، فأخذ العلم عن أشياخها. ثم عاد إلى دمشق ولزم الإفادة والتدريس، وانتفع به كثيرٌ من أبناء عصره، وتوفي بمكة حاجًّا، من مصنفاته شذرات الذهب في أخبار من ذهب، وله معطية الأمان من حنث الأيمان، وغيرها من الكتب."},{"id":3947,"title":"بدءُ السلطان العثماني محمد الرابع حملته السلطانية الأولى على روسيا .","date":["العام الهجري :1089","الشهر القمري : ربيع الأول","العام الميلادي :1678"],"text":"بدأ السلطان العثماني محمد الرابع حملته السلطانية الأولى على روسيا، وكانت تلك الحملة الأولى لسلطان عثماني على روسيا، حيث كان يقوم بهذه المهمة في السابق خان القرم."},{"id":3948,"title":"استيلاء الجيش العثماني على قلعة \"جهرين\" .","date":["العام الهجري :1089","الشهر القمري : رجب","العام الميلادي :1678"],"text":"تمكَّن الجيش العثماني من الاستيلاء على قلعة جهرين في أوكرانيا بعد حصار دام 32 يومًا، قتل خلاله 20 ألف جندي روسي وأوكراني."},{"id":3949,"title":"بدء السلطان العثماني محمد الرابع حملته السلطانية الثانية على روسيا .","date":["العام الهجري :1091","الشهر القمري : شوال","العام الميلادي :1680"],"text":"بدأ السلطان العثماني محمد الرابع حملته السلطانية الثانية على روسيا، وقد انتهت هذه الحملة بعقد صلح بين العثمانيين والروس."},{"id":3950,"title":"قتال بين الروس والعثمانيين انتهى بمعاهدة رادزين .","date":["العام الهجري :1093","العام الميلادي :1682"],"text":"بعد أن توفي الصدر الأعظم أحمد كوبريلي عام 1087هـ خلفه في الصدارة صهره قرة مصطفى، ولم يكن بكفاءة أحمد كوبريلي ووالده محمد باشا, فأثار القوزاق الذين استنجدوا بروسيا فوقعت الحرب بين الطرفين عام 1088هـ واستمرت حتى عام 1092هـ حتى عقدت معاهدة أنهت الحرب وبقيت الأمور كما كانت قبل الحرب، ولكن أصبح القوزاق أميلَ إلى أعدائهم الروس منهم إلى العثمانيين إخوانهم في السابق، وتمت المعاهدة المعروفة باسم معاهدة رادزين نسبة إلى المدينة التي وقعت فيها، والتي تقع جنوب غربي فارسوفيا (وارسو أو فرصوفيا عاصمة بولونيا)."},{"id":3951,"title":"وفاة السلطانة خديجة تارخان .","date":["العام الهجري :1093","الشهر القمري : جمادى الآخرة","العام الميلادي :1682"],"text":"هي السلطانة خديجة تارخان نائبة السلطنة في الدولة العثمانية، والتي تولت النيابة سنة 1651م؛ لصغر عمر ولدها السلطان محمد الرابع واستمرت في النيابة حتى عام 1656م. وخديجة من أصل أوكراني، وتوفيت عن 56 عامًا، وقد حازت أطول مدة لامرأة تحصل على صفة \"السلطانة - الوالدة\"، في التاريخ العثماني، حيث استمرت هذه الصفة لصيقة بها لمدة 34 عامًا."},{"id":3952,"title":"إعلان الدولة العثمانية الحرب على ألمانيا .","date":["العام الهجري :1093","الشهر القمري : شعبان","العام الميلادي :1682"],"text":"قامت الدولة العثمانية بإعلان الحرب على ألمانيا بعد 18 عامًا على صلح \"فاشفار\" الذي وقعه الجانبان."},{"id":3953,"title":"استيلاء القائد العثماني أوزون إبراهيم باشا على \"قلعة فولك\" .","date":["العام الهجري :1093","الشهر القمري : رمضان","العام الميلادي :1682"],"text":"تمكن القائد العثماني أوزون إبراهيم باشا من الاستيلاء على \"قلعة فولك\" الحصينة في سلوفاكيا إضافة إلى 28 قلعة أخرى بالمنطقة، وقد استطاع هذا القائد تحقيق السيطرة الكاملة على سلوفاكيا."},{"id":3954,"title":"حصار الدولة العثمانية لفيينا عاصمة النمسا .","date":["العام الهجري :1094","العام الميلادي :1682"],"text":"كان الصدر الأعظم قرة مصطفى قد سار عام 1092هـ لمحاربة النمسا بطلب من سكان الأقسام المجرية التي تخضع للنمسا بسبب استبداد النمسا المذهبي، وانتصر الصدر الأعظم في عدة معارك، ثم سار نحو فيينا وألقى عليها الحصار مدة شهرين من هذا العام, كان فتح فيينا يمثِّل حلمًا طالما راود سلاطينَ العثمانيين؛ لِما تمثِّلُه فيينا من أهمية استراتيجية للسيطرة على خطوط التجارة والمواصلات في القلب الأوروبي. فالسلطان سليمان القانوني حاصرها مرتين متتاليتين في عهده دون جدوى, فكان الأول منهما قبل 157 سنة في سنة 932, والمحاولة الثانية كانت سنة 939, وفي هذا الحصار الثالث كادت أن تُفتح فيينا أمام القوة العثمانية لولا نداءات البابا إلى الدول النصرانية وإثارة الهمم الصليبية، فوصلت قوات بولونيا وأمراء سكسونيا وبارفايا الألمان إلى العاصمة النمساوية، فهُزم المسلمون وانسحبوا بعد معارك طاحنة، واتجهوا نحو مدينة بودا، فوجد ملك بولونيا فرصة للثأر فتتبعهم يقتلُ كل من يستطيع قتله في مؤخرة العثمانيين، وكان هذا سبب قتل الصدر الأعظم قرة مصطفى حيث غضب عليه الخليفة وأمر بقتلِه وتنصيب إبراهيم باشا بدلَه."},{"id":3955,"title":"طرد الفرنسيين من الجزائر .","date":["العام الهجري :1094","العام الميلادي :1682"],"text":"عندما شنَّ الفرنسيون حملة صليبية كبيرة هدفها احتلال الجزائر في هذه السنة اضطر الداي بابا حسن إلى التفاوض معهم على أن يدفع لهم جزية كبيرة ويطلق جميع الأسرى الفرنسيين في الجزائر، لكن هذا الرضوخ من الداي لم يعجب طائفة رياس البحر وزعيمهم حسين ميزو مورتو الذين عبروا عن سخطهم بقتل الداي بابا حسن وتعيين حسين ميزو مورتو دايا مكانه، وبعد توليه الحكم أرسل خطابًا شديد اللهجة إلى قائد الحملة الفرنسية دوكين ينذره ويأمره بالخروج من الجزائر إلا أن دوكين كان مغترًّا بقوته، فرفض الاستماع لتهديد الداي الجديد الذي ما كان منه إلا أن أحضر القنصل الفرنسي المتهم بالتجسس على الجزائر وأدخله في فوهة أحد المدافع وقذفه على الفرنسيين فتطايرت أشلاؤه في عرض البحر، ولم يكتفِ بذلك بل أتبعه بعشرين أسيرًا فرنسيًّا آخر من أعوانه، وأمام هذا التحدي الكبير لم يجد دوكين بدًّا من الانسحاب من الجزائر."},{"id":3956,"title":"وقعت الدولة العثمانية معاهدة إستانبول مع البندقية .","date":["العام الهجري :1094","الشهر القمري : صفر","العام الميلادي :1683"],"text":"وقعت الدولة العثمانية معاهدة إستانبول مع البندقية. وبمقتضى هذه المعاهدة فُرض على البندقية تسديد غرامة قدرها ربع مليون قطعة ذهبية للدولة العثمانية."},{"id":3957,"title":"فتح القائد العثماني حسين باشا براتسلافا الألمانية .","date":["العام الهجري :1094","الشهر القمري : جمادى الآخرة","العام الميلادي :1683"],"text":"استطاع القائد العثماني حسين باشا أن يفتح براتسلافا الألمانية، وأن يغنم منها تاج إمبراطور ألمانيا، والذي كان موجودًا فيها."},{"id":3958,"title":"هزيمة الجيش العثماني في معركة \"ألمان داغي\" .","date":["العام الهجري :1094","الشهر القمري : رمضان","العام الميلادي :1683"],"text":"تعرض الجيش العثماني لهزيمة قاسية في معركة \"ألمان داغي\" أثناء حصاره لفيينا للمرة الثالثة، فعندما تداعت الدول الأوروبية بأقصى سرعة لنجدة فيينا من السقوط، وأعلن بابا روما الحرب الصليبية على العثمانيين، وأمر ملك بولندا سوبيسكي بنقض عهده مع العثمانيين، وأمر أيضًا أمراء ساكسونيا وبافاريا الألمان، وهم أقرب أمراء أوربا بالتوجه إلى فيينا بأقصى سرعة ممكنة، وكان قرة مصطفى قد وضع قوة عثمانية كبيرة يقودها أمير القرم مراد كراي عند جسر الدونة, وهنا حدث ما لم يكن في حسبان أحد لا من العثمانيين ولا من الأوربيين؛ إذ قام مراد كراي بخيانة عظمى للإسلام والمسلمين، وذلك بأنه سمح للأوربيين بالعبور من الجسر دون قتال، ثم حدثت خيانة عظمى أخرى من جانب أوغلو إبراهيم قائد ميمنة الجيش العثماني؛ إذ انسحب من القتال الذي اندلع بمنتهى العنف في 20 رمضان من هذه السنة، وكان لهذا الانسحاب الأثر الأكبر في هزيمة العثمانيين، وقد استطاع قرة مصطفى أن ينسحب بصورة منظمة من أرض المعركة بعد قتل 10 آلاف عثماني، وفي طريق العودة قام قرة مصطفى بإعدام كل من مراد كراي وأوغلو إبراهيم، ولكن لم يشفع ذلك له عند السلطان محمد الرابع الذي أمر بقتله, وتعدُّ هذه الهزيمة عند أسوار فيينا نقطةَ تحول فاصلة في التاريخ العثماني والأوروبي غيَّرَت مجرى التاريخ العالمي، واشتدت الحروب الصليبية على العثمانيين، وفقدت الجيوش العثمانية هيبتَها!!"},{"id":3959,"title":"انتصار الجيش العثماني على الجيش البولوني في معركة \"جكردلن\" .","date":["العام الهجري :1094","الشهر القمري : شوال","العام الميلادي :1683"],"text":"انتصر الجيش العثماني بقيادة محمد باشا على خصمه الجيش البولوني بقيادة الملك سوبياسكي في معركة \"جكردلن\"، وقتل من البولونيين في هذه المعركة 10 آلاف جندي."},{"id":3960,"title":"استيلاء الجيش البولوني والقوات الأوربية على قلعة \"إستركون\" .","date":["العام الهجري :1094","الشهر القمري : ذي القعدة","العام الميلادي :1683"],"text":"تمكن الجيش البولوني وعدد من القوات من أوربا من الاستيلاء على قلعة \"إستركون\" التابعة للدولة العثمانية بعد 22 يومًا من الحصار. وكانت هذه القلعة من أهم القلاع العثمانية في أوربا، والتي استمرت سيطرة العثمانيين عليها 128 عامًا."},{"id":3961,"title":"العثمانيون يفتحون (بودوليا) في بولندا و(فيينا) في النمسا .","date":["العام الهجري :1095","العام الميلادي :1683"],"text":"عندما حاول أمير ترانسلفانيا جورج راغوجي عدم الوفاء بالتزاماته المالية عزله العثمانيون وولوا مكانه ميخائيل أبافي، فكان هذا سببًا في قيام حرب تزعَّمها المجريون، ثم انضم لهم جماعة من الأوربيين في حرب صليبية كان العثمانيون لها بالمرصاد حتى وصلوا إلى حدود النمسا، ثم أحرز العثمانيون النصر عليهم، ثم حصلت حرب بين السويد وبولونيا (بولندا) فاستنجد ملك السويد بالعثمانيين على أن تصبح بولونيا تحت نفوذهم، فاتجه العثمانيون إلى بولونيا فقامت معارك ضارية فقد البولنديون فيها قلعة فامنج، حتى اضطر ميخائيل ملك بولونيا إلى عقد صلح مع العثمانيين تخلى بموجبه عن بودوليا وأوكرانيا، ثم عادت الحروب بينهم سِجالًا مرة أخرى، ولكن الأمر بقي لصالح العثمانيين؛ حيث عاد ملك بولندا للتخلي عن باقي أجزاء أوكرانيا وبودوليا للعثمانيين."},{"id":3962,"title":"بريطانيا تتخلى عن طنجة لسلطان مراكش .","date":["العام الهجري :1095","العام الميلادي :1683"],"text":"كانت طنجة مُستعمَرة من قبل البرتغاليين وبقيت تحتهم قرنين من الزمن ثم تنازلت الأميرة البرتغالية عنه لملك إنكلترا، فأصبحت تحت السيطرة البريطانية إلى أن قام إسماعيل السعدي ملك العلويين في مراكش بمحاصرة ثغر طنجة، واستمر الأمر ست سنوات إلى أن انتزعه في هذا العام من البريطانيين، وكان من أهم الثغور التجارية والمواقع الاستراتيجية على البحر الأبيض المتوسط."},{"id":3963,"title":"انتصار القائد العثماني سليم كيراي على ملك بولونيا .","date":["العام الهجري :1095","الشهر القمري : شوال","العام الميلادي :1684"],"text":"استطاع القائد العثماني القرمي سليم كيراي أن يهزم سوبياسكي ملك بولونيا في معركة كامانيجة."},{"id":3964,"title":"التحالف المقدس بين الصليبيين ضد العثمانيين .","date":["العام الهجري :1096","العام الميلادي :1684"],"text":"إن الانتصار الذي أحرزه الصليبيون في فك حصار فيينا زاد من أواصر الصليبية وشجعها على المضي، فكونت أوربا حلفًا ضم: النمسا، وبولونيا، والبندقية، ورهبان مالطة، والبابا، وروسيا، وسموه (الحِلف المقدس)؛ وذلك للوقوف في وجه المد الإسلامي الذي أصبح قريبًا من كل بيت في أوربا الشرقية؛ بسبب جهاد العثمانيين الأبطال، وبدأ الهجوم الصليبي على ديار الدولة العثمانية، وبدأ هذا التحالف بالعمل؛ فالنمسا بدأت تهاجم بلاد المجر وتمكنت من دخول مدينة بست وحاصرت مدينة بودا، ثم أخذت عدة مواضع، منها قلعة نوهزل، وكانت هذه الهزيمة سببًا في عزل الصدر إبراهيم باشا ونفيه إلى جزيرة رودوس، وعُين مكانه سليمان باشا الذي أسرع لنجدة بودا غير أن النمساويين قد دخلوها عنوة، وهُزم العثمانيون عام 1097هـ ثم هُزموا ثانية في العام التالي في موهاكز، وكانت أيضًا جيوش ملك بولونيا سوبيسكي تُغير على ولاية البغدان وتهددها، وأما سفن البندقية فكانت تُغير باستمرار على سواحل اليونان والمورة وتسندُها سفن أخرى من قِبَل البابا ورهبان مالطة، وتمكنت من دخول أثينا وكورنتا، وعدد آخر من المدن عام 1097هـ."},{"id":3965,"title":"هزيمة جيش البندقية في معركة شين .","date":["العام الهجري :1096","الشهر القمري : جمادى الأولى","العام الميلادي :1685"],"text":"تمكن القائد العثماني فندق مصطفى باشا- حاكم البوسنة- من هزيمة جيش البندقية في معركة شين."},{"id":3966,"title":"استسلام قلعة \"أويفار\" الخاضعة للدولة العثمانية .","date":["العام الهجري :1096","الشهر القمري : رمضان","العام الميلادي :1685"],"text":"كانت أويفار خاضعة للدولة العثمانية منذ 21 عامًا. ثم استسلمت قلعتها أويفار إلى دوق لورين بعد حصار دام 50 يومًا، وكان الاستيلاء على هذه القلعة سببًا في إقامة الأفراح في العالم النصراني. وقد كانت هذه القلعة خاضعة للألمان، فاستولى عليها العثمانيون سنة 1074، وهي من أمنع وأقوى قلاع أوربا."},{"id":3967,"title":"انتصار القائد العثماني سليم كيراي على ملك بولونيا في معركة بويان .","date":["العام الهجري :1096","الشهر القمري : ذي القعدة","العام الميلادي :1685"],"text":"تمكن القائد العثماني القرمي سليم كيراي من هزيمة ملك بولونيا سوبياسكي في معركة بويان، وخسر البولونيون في هذه المعركة 6 آلاف قتيل و5 آلاف أسير."},{"id":3968,"title":"وفاة القائد العثماني داماد ملك إبراهيم باشا .","date":["العام الهجري :1097","الشهر القمري : محرم","العام الميلادي :1685"],"text":"هو القائد العثماني الكهل الفذ داماد ملك إبراهيم باشا، كان اسمه شيطان إبراهيم باشا، استبدل به السلطان محمد الرابع ملك إبراهيم باشا بعد انتصار القوات العثمانية في معركة كرز إلياس على الألمان، وعينه قائدًا بدل بكري مصطفى باشا, وبعد سقوط أويفار بيد الألمان أصدر رئيس الوزراء العثماني قرة إبراهيم باشا أمرًا بقتل داماد ملك إبراهيم باشا متَّهِمًا إياه بالمسؤولية عن سقوطها, وقيل إن السبب الحقيقي في قتله أن الصدر قرة إبراهيم كان يخشى أن يحتل ملك إبراهيم مكانه الذي فقده بعد قتله لمنافسه ملك إبراهيم باشا بخمسة عشر يومًا, وقيل بسبب رفضه القيام بحملات خارجية."},{"id":3969,"title":"استيلاء القائد البندقي موروسيني على قلعة نافارين من العثمانيين .","date":["العام الهجري :1097","الشهر القمري : رجب","العام الميلادي :1686"],"text":"تمكن القائد البندقي موروسيني من الاستيلاء على قلعة نافارين في جزيرة المورة باليونان من العثمانيين بعد حصار استمر 13 يومًا تقريبًا."},{"id":3970,"title":"سيطرة الجيش الألماني وحلفائه على قلعة \"بودين\" في بودابست .","date":["العام الهجري :1097","الشهر القمري : شوال","العام الميلادي :1686"],"text":"تمكن الجيش الألماني الضخم وحلفاؤه من الأوربيين من السيطرة على قلعة ومدينة \"بودين\" في بودابست، بعد دفاع عثماني مجيد، سقط خلاله آلاف القتلى من العثمانيين، وكان العثمانيون قد فتحوها قبل 160 عامًا إبَّان حكم سليمان القانوني، وكان سقوطها من أكبر المصائب العثمانية."},{"id":3971,"title":"سقوط مدينة بودابست المجرية في يد الألمان وطرد الأتراك منها .","date":["العام الهجري :1098","العام الميلادي :1686"],"text":"كان العثمانيون قد حاصروا فيينا وكادوا يفتحونها لولا أن الصليبيين تحالفوا بفعل نداءات البابا لهم، فقاموا بالتكالب على الدولة العثمانية كلٌّ من طرف، فوصلت القوات من كل مكان من بولونيا وبافاريا الألمان إلى فيينا لفك الحصار، ثم بعد فك الحصار عقد البابا حلفًا مع الروس والألمان والبولنديين والبنادقة على طرد العثمانيين من المجر، فقامت كل دولة بالهجوم على الدولة العثمانية من طرق؛ لتشتيت قواها، فاستطاع الألمان أن يستعيدوا منها بودا بست في هذا العام."},{"id":3972,"title":"انتصار الجيش العثماني على \"جيش الاتفاق\" في معركة أوساك .","date":["العام الهجري :1098","الشهر القمري : شعبان","العام الميلادي :1687"],"text":"انتصر الجيش العثماني على ما يسمى بـ \"جيش الاتفاق\" الذي كوَّنته أوربا النصرانية لحرب الدولة العثمانية في معركة \"أوساك\" قرب المجر."},{"id":3973,"title":"استيلاء البنادقة على قلعة كورون من العثمانيين .","date":["العام الهجري :1098","الشهر القمري : رمضان","العام الميلادي :1687"],"text":"تمكن القائد البندقي موروسيني من الاستيلاء على قلعة كورون في اليونان من العثمانيين بعد حصارهم لها لمدة شهر كامل."},{"id":3974,"title":"هزيمة الجيش العثماني من قِبَل جيش الاتفاق الأوربي .","date":["العام الهجري :1098","الشهر القمري : شوال","العام الميلادي :1687"],"text":"تعرض الجيش العثماني لهزيمة قاسية في صحراء موهاج المجرية أمام جيش الاتفاق الذي كونته أوربا النصرانية لحرب العثمانيين، وقد قتل خلالها 20 ألف عثماني، مرة واحدة."},{"id":3975,"title":"انتصار العثمانيين على ملك بولونيا .","date":["العام الهجري :1098","الشهر القمري : شوال","العام الميلادي :1687"],"text":"قام العثمانيون بهزيمة ملك بولونيا سوبياسكي هزيمة كبيرة، وذلك قرب قلعة كامانيجة."},{"id":3976,"title":"استيلاء الجيش البندقي على مدينة أثينا من العثمانيين .","date":["العام الهجري :1098","الشهر القمري : ذي القعدة","العام الميلادي :1687"],"text":"تمكن الجيش البندقي الذي تسانده إسبانيا وألمانيا ومالطة والسويد من الاستيلاء على مدينة أثينا من العثمانيين، وقام بتخريبها بشكل فظيع، وقام الأرثوذكس بذبح الكاثوليك في المدينة بلا رحمة."},{"id":3977,"title":"خلع السلطان العثماني محمد الرابع وتولية أخيه سليمان الثاني .","date":["العام الهجري :1099","الشهر القمري : محرم","العام الميلادي :1687"],"text":"لما تتالت الهزائم على العثمانيين وحدثت الفوضى بسبب ذلك، اتفق العلماء والوزير على عزل السلطان محمد الرابع بن إبراهيم الأول، فتم ذلك في هذا العام بعد أن أمضى في الحكم أربعين سنة وخمسة أشهر، أعاد خلال مدة حكمه هيبة الدولة وقوتها، كما أعاد عمليات الفتح في أوربا، وتولى قيادة جيوش الدولة, ويعتبر هو آخر القادة الفاتحين في التاريخ الإسلامي، وتمت تولية أخيه سليمان الثاني في الثاني من محرم الذي كان يزيد عمره على أربع وأربعين عامًا."},{"id":3978,"title":"استيلاء الجنرال المجري كارفا على مركز إيالة أكري من العثمانيين .","date":["العام الهجري :1099","الشهر القمري : صفر","العام الميلادي :1687"],"text":"تمكن الجنرال المجري كارفا من الاستيلاء على مركز إيالة أكري من العثمانيين، وبذلك خرج شمال المجر من الحكم العثماني. وقد كان بالمدينة التي فتحها العثمانيون قبل 91 عامًا من تاريخ سقوطها حوالي 41 مسجدًا هُدِّمت جميعًا إلا مأذنة واحدة ما زالت باقية حتى الآن، وتحول جامعها الكبير إلى كنيسة القديس ليوبولد!!"},{"id":3979,"title":"سقوط قلعة بلغراد في أيدي الألمان وتحويل مائة مسجد إلى كنائس .","date":["العام الهجري :1099","الشهر القمري : ذي القعدة","العام الميلادي :1688"],"text":"سقطت قلعة بلغراد في أيدي الألمان، بعد تسع وعشرين يومًا من حصار الجيش العثماني بداخلها، وتم تحويل مائة مسجد في المدينة إلى كنائس، بعد ذبح المسلمين الموجودين فيها. وكانت بلجراد مدينة إسلاميَّة لعدة قرون من حيث العمران وحركة العلم ورفع راية الجهاد, ثم تحوَّلت بعد سقوطها بسنوات إلى محاربة المسلمين، الذين حوَّلوها إلى إحدى أعظم مدن أوربا حضارة. وقت أنْ كانت أوربا تعيش في ظلمات الجهل والتخلُّف، وقد صارت اليوم مدينة نصرانية في ظل الحرب الشَّرسة التي تعرَّض لها الإسلام والمسلمون في هذه الأرض!"},{"id":3980,"title":"هزيمة الدولة العثمانية أمام النمسا .","date":["العام الهجري :1100","العام الميلادي :1688"],"text":"انتهز الأعداء الفوضى التي جرت بعد تولي السلطان الجديد سليمان الثاني حيث تمرد الجند وقتلوا الصدر الأعظم سياوس باشا وسَبَوا نساءه، فتقدم الأعداء في أملاك الدولة العثمانية, فأخذت النمسا كثيرًا من المواقع والمدن، ومنها بلغراد، كما أخذت البندقية سواحل دالماسيا (السواحل الشرقية لبحر الأدرياتيك) وبعض المواطن في بلاد اليونان وتوالت الهزائم."},{"id":3981,"title":"انتصار القائد القرمي سليم كيراي على الجيش الروسي .","date":["العام الهجري :1100","الشهر القمري : شعبان","العام الميلادي :1689"],"text":"تمكن القائد القرمي التابع للدولة العثمانية سليم كيراي من هزيمة الجيش الروسي، المكون من 300 ألف جندي، والذي اقترب من حدود القرم."}]
